async def get_cross_chat_delivery_record(
    envelope_id: str | None,
    exchange_leg_id: str | None,
) -> dict[str, Any] | None:
    if exchange_leg_id:
        return await CROSS_CHAT.get_exchange_leg(str(exchange_leg_id))
    if envelope_id:
        return await CROSS_CHAT.get(str(envelope_id))
    return None


async def update_cross_chat_delivery_record(
    envelope_id: str | None,
    exchange_leg_id: str | None,
    *,
    expected: set[str] | None = None,
    **changes: Any,
) -> dict[str, Any] | None:
    if exchange_leg_id:
        return await CROSS_CHAT.update_exchange_leg(
            str(exchange_leg_id),
            expected=expected,
            **changes,
        )
    if envelope_id:
        return await CROSS_CHAT.update(
            str(envelope_id),
            expected=expected,
            **changes,
        )
    return None


def ensure_codex_thread_not_pending_fork_cleanup(thread_id: Any) -> None:
    """Fence provider identities while post-crash fork cleanup owns them."""

    clean_thread_id = str(thread_id or "").strip()
    if clean_thread_id and clean_thread_id in ABANDONED_FORK_PROVIDER_THREADS:
        raise HTTPException(
            status_code=409,
            detail=(
                "this Codex thread is being retired after an interrupted fork; "
                "retry after cleanup completes"
            ),
        )


def session_references_codex_thread(
    session: dict[str, Any],
    thread_id: str,
) -> bool:
    """Return whether a chat owns a Codex identity, active or parked."""

    codex_thread_id = str(session.get("codex_thread_id") or "").strip()
    active_session_id = (
        str(session.get("session_id") or "").strip()
        if str(session.get("backend") or DEFAULT_BACKEND).strip().lower()
        == BACKEND_CODEX
        else ""
    )
    return thread_id in {codex_thread_id, active_session_id}


def session_codex_thread_id(session: dict[str, Any]) -> str:
    """Return the chat's Codex root whether Codex is active or parked."""

    parked = str(session.get("codex_thread_id") or "").strip()
    if parked:
        return parked
    if (
        str(session.get("backend") or DEFAULT_BACKEND).strip().lower()
        == BACKEND_CODEX
    ):
        return str(session.get("session_id") or "").strip()
    return ""


def session_lifecycle_lock(session_id: str) -> asyncio.Lock:
    lock = SESSION_LIFECYCLE_LOCKS.get(session_id)
    if lock is None:
        lock = asyncio.Lock()
        SESSION_LIFECYCLE_LOCKS[session_id] = lock
    return lock


def explicit_stop_in_progress(session_id: str) -> bool:
    """Return whether explicit Stop still owns turn-admission cleanup."""

    operation = EXPLICIT_STOP_OPERATIONS.get(session_id)
    return operation is not None and not operation.done()


def detached_stop_in_progress(session_id: str) -> bool:
    """Return whether an inner Stop teardown still owns this session."""

    return any(
        not task.done()
        for task in DETACHED_STOP_TASKS_BY_SESSION.get(session_id, ())
    )


def stop_cleanup_in_progress(session_id: str) -> bool:
    """Return whether either layer of explicit Stop can affect this chat."""

    return (
        explicit_stop_in_progress(session_id)
        or detached_stop_in_progress(session_id)
    )


QUEUE_FENCE_LOGGED_AT: dict[tuple[str, str], float] = {}


def queue_promotion_fence(session_id: str) -> str | None:
    """Name the process-wide or per-chat fence that makes promotion a no-op.

    Reconciliation used to schedule a promotion that then returned silently
    from ``_start_next_queued_turn_locked``; with two clients polling health
    that produced a per-second loop with no indication of the real blocker.
    """

    if stop_cleanup_in_progress(session_id):
        return "explicit_stop"
    blocker = managed_server_update_blocker()
    if blocker == MANAGED_SERVER_RESTART_ACTIVE_DETAIL:
        return "server_restart"
    if blocker:
        return "server_update"
    return None


def log_queue_promotion_fence(session_id: str, fence: str, reason: str) -> None:
    """Log a fenced promotion at most once per minute per chat and fence."""

    now = time.monotonic()
    key = (session_id, fence)
    last = QUEUE_FENCE_LOGGED_AT.get(key)
    if last is not None and now - last < QUEUE_FENCE_LOG_INTERVAL_SECONDS:
        return
    QUEUE_FENCE_LOGGED_AT[key] = now
    if len(QUEUE_FENCE_LOGGED_AT) > 4096:
        stale = [
            entry_key
            for entry_key, logged_at in QUEUE_FENCE_LOGGED_AT.items()
            if now - logged_at >= QUEUE_FENCE_LOG_INTERVAL_SECONDS
        ]
        for entry_key in stale:
            QUEUE_FENCE_LOGGED_AT.pop(entry_key, None)
    logger.warning(
        "queue promotion fenced session=%s fence=%s reason=%s "
        "visible_queue_count=%s",
        session_id,
        fence,
        reason,
        len(QUEUED_TURNS.get(session_id) or ()),
    )


def explicit_stop_session_ids() -> set[str]:
    """Snapshot chats whose detached Stop cleanup still blocks replacement."""

    outer = {
        session_id
        for session_id, operation in EXPLICIT_STOP_OPERATIONS.items()
        if not operation.done()
    }
    inner = {
        session_id
        for session_id, tasks in DETACHED_STOP_TASKS_BY_SESSION.items()
        if any(not task.done() for task in tasks)
    }
    return outer | inner


def ensure_session_not_initializing(session_id: str) -> None:
    session = STORE.sessions.get(session_id)
    if isinstance(session, dict) and session.get("_fork_initializing"):
        raise HTTPException(status_code=409, detail="session fork is still initializing")


def ensure_session_not_deleting(session_id: str) -> None:
    ensure_session_not_initializing(session_id)
    if (
        session_id in DELETING_SESSIONS
        or session_id in DELETED_SESSION_TOMBSTONES
    ):
        raise HTTPException(status_code=409, detail="session is being deleted")


def register_session_task(
    registry: dict[str, set[asyncio.Task[Any]]],
    session_id: str,
    task: asyncio.Task[Any],
) -> None:
    tasks = registry.setdefault(session_id, set())
    tasks.add(task)

    def discard(completed: asyncio.Task[Any]) -> None:
        current = registry.get(session_id)
        if current is None:
            return
        current.discard(completed)
        if not current:
            registry.pop(session_id, None)

    task.add_done_callback(discard)


async def wait_for_session_tasks(
    registry: dict[str, set[asyncio.Task[Any]]],
    session_id: str,
    *,
    timeout: float = CODEX_SESSION_CLEANUP_TIMEOUT_SECONDS,
) -> bool:
    current = asyncio.current_task()
    tasks = [
        task
        for task in tuple(registry.get(session_id) or ())
        if task is not current and not task.done()
    ]
    if not tasks:
        return True
    _done, pending = await asyncio.wait(tasks, timeout=max(0.01, timeout))
    return not pending


def cached_codex_permission_profiles(
    cwd: str,
    manager: CodexAppServerManager | None,
) -> list[dict[str, Any]] | None:
    cached = CODEX_PERMISSION_PROFILES_CACHE.get(cwd)
    generation = manager.generation if manager is not None and manager.ready else None
    if cached is None or generation is None:
        return None
    cached_generation, cached_at, profiles = cached
    if (
        cached_generation != generation
        or time.monotonic() - cached_at >= CODEX_PERMISSION_PROFILES_CACHE_SECONDS
    ):
        CODEX_PERMISSION_PROFILES_CACHE.pop(cwd, None)
        return None
    return list(profiles)


def acquire_codex_interactive_control_lease(thread_id: str) -> None:
    count = CODEX_INTERACTIVE_CONTROL_THREAD_COUNTS.get(thread_id, 0) + 1
    CODEX_INTERACTIVE_CONTROL_THREAD_COUNTS[thread_id] = count
    CODEX_INTERACTIVE_CONTROL_THREADS.add(thread_id)


def release_codex_interactive_control_lease(thread_id: str) -> None:
    count = CODEX_INTERACTIVE_CONTROL_THREAD_COUNTS.get(thread_id, 0)
    if count <= 1:
        CODEX_INTERACTIVE_CONTROL_THREAD_COUNTS.pop(thread_id, None)
        CODEX_INTERACTIVE_CONTROL_THREADS.discard(thread_id)
        return
    CODEX_INTERACTIVE_CONTROL_THREAD_COUNTS[thread_id] = count - 1


async def reset_codex_ephemeral_runtime_metadata() -> None:
    """Clear process-owned Codex state after transport shutdown or restart."""
    CODEX_GOAL_SYNC_GENERATIONS.clear()
    CODEX_QUARANTINED_GOAL_THREADS.clear()
    with CODEX_SUBAGENT_INDEX_LOCK:
        CODEX_SUBAGENT_LIVE_GENERATIONS.clear()
    changed = False
    async with STORE._lock:
        for session in STORE.sessions.values():
            if str(session.get("backend") or DEFAULT_BACKEND) != BACKEND_CODEX:
                continue
            reset_values = {
                "codex_thread_status": {"type": "notLoaded"},
                "codex_pending_interaction_count": 0,
                "codex_needs_user_action": False,
            }
            for key, value in reset_values.items():
                if session.get(key) != value:
                    session[key] = value
                    changed = True
            cached_goal = session.get("codex_goal")
            if (
                isinstance(cached_goal, dict)
                and str(cached_goal.get("status") or "") == "active"
            ):
                session["codex_goal"] = {
                    **cached_goal,
                    "status": "paused",
                }
                session["_codex_goal_reconciliation_required"] = {
                    "thread_id": str(session_provider_id(session) or "") or None,
                    "recorded_at": now_iso(),
                    "reason": "Codex app-server stopped without a live run owner.",
                }
                changed = True
            if "_codex_token_usage_terminal" in session:
                session.pop("_codex_token_usage_terminal", None)
                changed = True
        if changed:
            await STORE.save()

