async def join_cancelled_tasks(*tasks: Any) -> None:
    """Await already-cancelled tasks without letting any of them raise."""

    if tasks:
        await asyncio.gather(*tasks, return_exceptions=True)


async def bounded_shutdown_phase(
    name: str,
    awaitable: Any,
    *,
    timeout: float | None = None,
) -> bool:
    """Run one lifespan shutdown phase under a deadline; never raise.

    A single wedged join (a provider that ignores SIGTERM, a lock held by a
    dead task) must not prevent the phases after it - in particular provider
    teardown - from running. Returns True when the phase completed in time.
    """

    budget = (
        SERVER_SHUTDOWN_PHASE_TIMEOUT_SECONDS
        if timeout is None
        else max(0.0, float(timeout))
    )
    try:
        phase_task = asyncio.ensure_future(awaitable)
    except Exception as exc:
        logger.warning(
            "shutdown phase %s failed error=%s",
            name,
            concise_error_message(exc),
        )
        return False

    def consume_shutdown_straggler(completed: asyncio.Task[Any]) -> None:
        SERVER_SHUTDOWN_STRAGGLERS.discard(completed)
        with suppress(BaseException):
            completed.result()

    try:
        done, _pending = await asyncio.wait({phase_task}, timeout=budget)
    except asyncio.CancelledError:
        phase_task.cancel()
        SERVER_SHUTDOWN_STRAGGLERS.add(phase_task)
        phase_task.add_done_callback(consume_shutdown_straggler)
        # Matches the previous per-await suppress: a cancelled join never
        # aborts the remaining teardown.
        return False
    if phase_task not in done:
        # asyncio.wait returns at the deadline without waiting for cancellation
        # acknowledgement. A provider coroutine may suppress CancelledError;
        # retain and consume it later, but never let that defeat this bound or
        # starve the remaining shutdown phases.
        phase_task.cancel()
        SERVER_SHUTDOWN_STRAGGLERS.add(phase_task)
        phase_task.add_done_callback(consume_shutdown_straggler)
        logger.warning(
            "shutdown phase %s did not finish within %.0fs; continuing",
            name,
            budget,
        )
        return False
    try:
        phase_task.result()
    except asyncio.CancelledError:
        return False
    except Exception as exc:
        logger.warning(
            "shutdown phase %s failed error=%s",
            name,
            concise_error_message(exc),
        )
        return False
    return True


@asynccontextmanager
async def lifespan(app: FastAPI):
    global SERVER_SHUTTING_DOWN, QUEUE_RECOVERY_TASK
    SERVER_SHUTTING_DOWN = False
    await STORE.load()
    # Prime the managed-service ownership proof once, off the loop, so the
    # restart controls never depend on a fresh launchctl/cgroup probe later.
    with suppress(Exception):
        await asyncio.to_thread(managed_server_service_kind)
    await JOBS.load()
    ensure_dirs()
    # A forced kill of the previous instance cannot reach provider children in
    # their own sessions; reap anything the registry says was left behind.
    with suppress(Exception):
        await asyncio.to_thread(sweep_orphaned_provider_children)
    SECURE_PEER_RUNTIME.set_delivery_target_validator(
        secure_peer_delivery_target_available
    )
    await asyncio.to_thread(TEAM_HUB_RUNTIME.initialize)
    await asyncio.to_thread(scrub_tmux_global_secret_environment)
    await CROSS_CHAT.initialize()
    startup_restart_status = read_server_restart_status()
    forced_restart_request_id = (
        str(startup_restart_status.get("request_id") or "")[:128]
        if (
            str(startup_restart_status.get("phase") or "")
            in SERVER_RESTART_ACTIVE_PHASES
            and startup_restart_status.get("_forced") is True
            and str(startup_restart_status.get("_source_instance_id") or "")
            not in {"", SERVER_INSTANCE_ID}
        )
        else ""
    )
    reconcile_server_restart_status_after_startup()
    clear_imported_active_runs()
    startup_update_status = await reconcile_server_update_status_after_startup()
    active_update_schedule_id = (
        str(startup_update_status.get("schedule_id") or "").strip()
        if managed_server_update_is_pending(startup_update_status)
        else None
    )
    # A completed/failed update, an offline cancellation, or replacement by a
    # new reservation may leave exact automatic occurrences parked in the
    # durable job registry. Rearm untouched revisions except those owned by
    # the one reservation that is still live.
    await JOBS.resume_update_parked(
        active_schedule_id=active_update_schedule_id,
    )
    abandoned_compaction_count = (
        await recover_abandoned_codex_compactions_after_start(
            forced_restart_request_id=(forced_restart_request_id or None),
        )
    )
    abandoned_turn_count = await recover_abandoned_turns_after_start(
        forced_restart_request_id=(forced_restart_request_id or None),
    )
    removed_authority_files = (
        await purge_cross_chat_authority_files_after_restart()
    )
    digest_job_count = await load_handoff_digest_jobs()
    recovered_scheduled_run_count = (
        await JOBS.reconcile_admitted_runs_after_restart()
    )
    JOBS.start_scheduler()
    async def recover_queue_before_admission() -> tuple[int, int]:
        global QUEUE_RECOVERY_TASK
        succeeded = False
        try:
            result = await recover_queued_turns_after_start()
            succeeded = True
            return result
        except asyncio.CancelledError:
            raise
        except Exception:
            # Keep the failed task installed as a fail-closed admission fence;
            # health and administrative recovery remain available.
            logger.exception(
                "queued turn startup recovery failed; turn admission remains closed"
            )
            raise
        finally:
            owner = asyncio.current_task()
            if succeeded and QUEUE_RECOVERY_TASK is owner:
                QUEUE_RECOVERY_TASK = None

    queue_recovery_task = asyncio.create_task(
        recover_queue_before_admission(),
        name="queued-turn-startup-recovery",
    )
    QUEUE_RECOVERY_TASK = queue_recovery_task
    server_update_pending_waiter_task = asyncio.create_task(
        server_update_pending_waiter_loop(),
        name="server-update-pending-waiter",
    )

    async def reconcile_digests_after_queue_recovery() -> None:
        with suppress(Exception):
            await queue_recovery_task
        await reconcile_handoff_digest_jobs()

    digest_recovery_task = asyncio.create_task(reconcile_digests_after_queue_recovery())

    async def reconcile_cross_chat_after_queue_recovery() -> None:
        with suppress(Exception):
            await queue_recovery_task
        await reconcile_cross_chat_handoffs()
        await reconcile_cross_chat_exchanges()

    cross_chat_recovery_task = asyncio.create_task(reconcile_cross_chat_after_queue_recovery())
    cross_chat_expiry_task = asyncio.create_task(cross_chat_exchange_expiry_loop())

    async def secure_peer_maintenance_loop() -> None:
        while True:
            try:
                await asyncio.to_thread(SECURE_PEER_RUNTIME.maintenance_once)
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                logger.warning(
                    "secure peer maintenance deferred error=%s",
                    concise_error_message(exc),
                )
            await asyncio.sleep(SECURE_PEER_HEARTBEAT_SECONDS)

    secure_peer_task = asyncio.create_task(secure_peer_maintenance_loop())

    secure_peer_reconciliation_ready = asyncio.Event()

    async def secure_peer_connector_loop() -> None:
        with suppress(Exception):
            await queue_recovery_task
        try:
            await reconcile_secure_peer_deliveries()
        except Exception as exc:
            logger.warning(
                "secure peer startup reconciliation deferred error=%s",
                concise_error_message(exc),
            )
        finally:
            secure_peer_reconciliation_ready.set()
        while True:
            try:
                await secure_peer_connector_once()
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                logger.warning(
                    "secure peer connector deferred error=%s",
                    concise_error_message(exc),
                )
            await asyncio.sleep(2)

    secure_peer_connector_task = asyncio.create_task(
        secure_peer_connector_loop()
    )

    async def secure_peer_response_outbox_loop() -> None:
        await secure_peer_reconciliation_ready.wait()
        while True:
            try:
                await reconcile_secure_peer_response_outbox()
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                logger.warning(
                    "secure peer response outbox deferred error=%s",
                    concise_error_message(exc),
                )
            await asyncio.sleep(2)

    secure_peer_response_outbox_task = asyncio.create_task(
        secure_peer_response_outbox_loop()
    )
    startup_abandoned_fork_threads = set(ABANDONED_FORK_PROVIDER_THREADS)
    abandoned_fork_cleanup_task = asyncio.create_task(
        cleanup_abandoned_fork_provider_threads(startup_abandoned_fork_threads)
    )
    host_monitor_task = asyncio.create_task(host_monitor_loop())
    history_search_task = asyncio.create_task(history_search_index_loop())
    runtime_probe_task = asyncio.create_task(asyncio.to_thread(refresh_runtime_diagnostics, force=True))
    if CONFIG_ENV_APPLIED:
        # Names only - these can be provider credentials.
        logger.info(
            "loaded %d config-file environment variable(s) from %s: %s",
            len(CONFIG_ENV_APPLIED),
            CONFIG_ENV_FILE,
            ", ".join(CONFIG_ENV_APPLIED),
        )
    logger.info(
        "agent server ready state=%s sessions=%d jobs=%d digests=%d recovered_scheduled_runs=%d abandoned_turns=%d abandoned_compactions=%d authority_removed=%d queue_recovery=background",
        STATE_DIR,
        len(STORE.sessions),
        len(JOBS.jobs),
        digest_job_count,
        recovered_scheduled_run_count,
        abandoned_turn_count,
        abandoned_compaction_count,
        removed_authority_files,
    )
    try:
        yield
    finally:
        SERVER_SHUTTING_DOWN = True
        # Every phase below is bounded by SERVER_SHUTDOWN_PHASE_TIMEOUT_SECONDS
        # (see bounded_shutdown_phase) so one stuck join cannot starve the
        # provider teardown that follows it. The order is load-bearing.
        #
        # Stop startup reconciliation before taking the delivery-task
        # snapshot; otherwise it could enqueue a new retry owner after the
        # shutdown cancellation pass.
        #
        # The scheduler can admit provider work and mutate both registries.
        # Retire it before flushing state or closing either provider manager.
        await bounded_shutdown_phase(
            "job-scheduler",
            JOBS.stop_scheduler(),
        )
        # Land the coalesced sessions.json write first: a restart watchdog can
        # kill later phases, and the trailing flush covers marks they make.
        await bounded_shutdown_phase(
            "sessions-flush-early",
            STORE.flush_pending_save(),
        )
        explicit_stop_tasks = tuple({
            *EXPLICIT_STOP_OPERATIONS.values(),
            *DETACHED_STOP_TASKS,
        })
        for explicit_stop_task in explicit_stop_tasks:
            explicit_stop_task.cancel()
        await bounded_shutdown_phase(
            "explicit-stop-operations",
            join_cancelled_tasks(*explicit_stop_tasks),
        )
        health_queue_reconcile_task = HEALTH_QUEUE_RECONCILE_STATE.get("task")
        if isinstance(health_queue_reconcile_task, asyncio.Task):
            health_queue_reconcile_task.cancel()
        claude_stop_fence_retry_tasks = tuple(
            CLAUDE_STOP_FENCE_RETRY_TASKS.values()
        )
        claude_stop_fence_attempt_tasks = tuple(
            task
            for tasks in CLAUDE_STOP_FENCE_ATTEMPT_TASKS.values()
            for task in tasks
        )
        for claude_stop_fence_retry_task in claude_stop_fence_retry_tasks:
            claude_stop_fence_retry_task.cancel()
        for claude_stop_fence_attempt_task in claude_stop_fence_attempt_tasks:
            claude_stop_fence_attempt_task.cancel()
        cross_chat_recovery_task.cancel()
        cross_chat_expiry_task.cancel()
        digest_recovery_task.cancel()
        queue_recovery_task.cancel()
        server_update_pending_waiter_task.cancel()
        await bounded_shutdown_phase(
            "startup-reconciliation",
            join_cancelled_tasks(
                cross_chat_recovery_task,
                cross_chat_expiry_task,
                digest_recovery_task,
                queue_recovery_task,
                server_update_pending_waiter_task,
                *(
                    (health_queue_reconcile_task,)
                    if isinstance(health_queue_reconcile_task, asyncio.Task)
                    else ()
                ),
                *claude_stop_fence_retry_tasks,
                *claude_stop_fence_attempt_tasks,
            ),
        )
        if QUEUE_RECOVERY_TASK is queue_recovery_task:
            QUEUE_RECOVERY_TASK = None
        direct_delivery_tasks = tuple(CROSS_CHAT_DIRECT_DELIVERY_TASKS)
        for direct_delivery_task in direct_delivery_tasks:
            direct_delivery_task.cancel()
        await bounded_shutdown_phase(
            "cross-chat-direct-delivery",
            join_cancelled_tasks(*direct_delivery_tasks),
        )
        status_wake_tasks = tuple(CROSS_CHAT_STATUS_WAKE_TASKS)
        for status_wake_task in status_wake_tasks:
            status_wake_task.cancel()
        await bounded_shutdown_phase(
            "cross-chat-status-wake",
            join_cancelled_tasks(*status_wake_tasks),
        )
        await bounded_shutdown_phase(
            "terminal-attachments",
            TERMINAL_ATTACHMENTS.close_admission_and_all(permanent=True),
        )
        await bounded_shutdown_phase("port-tunnels", PORT_TUNNELS.close_all())
        secure_peer_task.cancel()
        secure_peer_connector_task.cancel()
        secure_peer_response_outbox_task.cancel()
        await bounded_shutdown_phase(
            "secure-peer-loops",
            join_cancelled_tasks(
                secure_peer_task,
                secure_peer_connector_task,
                secure_peer_response_outbox_task,
            ),
        )
        await bounded_shutdown_phase("team-hub", TEAM_HUB_RUNTIME.shutdown())
        await bounded_shutdown_phase(
            "secure-peer-runtime",
            asyncio.to_thread(SECURE_PEER_RUNTIME.shutdown),
        )
        await bounded_shutdown_phase("claude-sdk", close_claude_sdk_manager())
        await bounded_shutdown_phase(
            "codex-app-server",
            close_codex_app_server_manager(),
        )
        # Provider finalizers may enqueue one last durable status/outbox task
        # while their managers close. No producer remains after both manager
        # joins, so this second drain is the terminal task boundary.
        trailing_cross_chat_tasks = tuple({
            *CROSS_CHAT_DIRECT_DELIVERY_TASKS,
            *CROSS_CHAT_STATUS_WAKE_TASKS,
        })
        for trailing_cross_chat_task in trailing_cross_chat_tasks:
            trailing_cross_chat_task.cancel()
        await bounded_shutdown_phase(
            "cross-chat-trailing",
            join_cancelled_tasks(*trailing_cross_chat_tasks),
        )
        abandoned_fork_cleanup_task.cancel()
        host_monitor_task.cancel()
        history_search_task.cancel()
        runtime_probe_task.cancel()
        await bounded_shutdown_phase(
            "background-loops",
            join_cancelled_tasks(
                abandoned_fork_cleanup_task,
                host_monitor_task,
                history_search_task,
                runtime_probe_task,
            ),
        )
        # Provider HTTP calls cannot survive this process. All background and
        # provider-turn owners that can touch a live exchange are now joined;
        # wake and detach leftovers under their stable per-exchange locks.
        await bounded_shutdown_phase(
            "cross-chat-live-waiters",
            settle_cross_chat_live_waiters_for_shutdown(),
        )
        # Every session mutator above is joined; land the last coalesced
        # sessions.json write before the loop stops.
        await bounded_shutdown_phase(
            "sessions-flush",
            STORE.flush_pending_save(),
        )


class AgentsServerCORSMiddleware(CORSMiddleware):
    """Leave the mounted Hub's exact-origin policy entirely to the Hub."""

    async def __call__(self, scope: Any, receive: Any, send: Any) -> None:
        path = str(scope.get("path") or "") if isinstance(scope, dict) else ""
        if (
            path == TEAM_HUB_MOUNT_PATH
            or path.startswith(TEAM_HUB_MOUNT_PATH + "/")
            or path == TEAM_HUB_SERVER_SESSION_MOUNT_PATH
            or path.startswith(TEAM_HUB_SERVER_SESSION_MOUNT_PATH + "/")
            or path == "/api/admin/secure-peers/v1"
            or path.startswith("/api/admin/secure-peers/v1/")
            or path.startswith("/api/team-hub-secure/")
        ):
            await self.app(scope, receive, send)
            return
        await super().__call__(scope, receive, send)


app = FastAPI(title="AgentsServer", lifespan=lifespan)
app.add_middleware(
    AgentsServerCORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)
app.mount(TEAM_HUB_MOUNT_PATH, TEAM_HUB_RUNTIME, name="team-hub")
app.mount(
    TEAM_HUB_SERVER_SESSION_MOUNT_PATH,
    TEAM_HUB_RUNTIME,
    name="team-hub-server-session",
)

