def queued_turn_backend(session_id: str, item: dict[str, Any]) -> str:
    session = STORE.sessions.get(session_id) or {}
    return str(
        item.get("backend") or session.get("backend") or DEFAULT_BACKEND
    ).strip().lower()


def codex_subagent_has_live_owner(
    thread_id: str,
    state: dict[str, Any],
) -> bool:
    """Distinguish a live child from a persisted pre-restart running card."""

    status = normalize_subagent_status(
        state.get("subagent_status") or state.get("status")
    )
    if status not in {"starting", "running"}:
        return False
    with CODEX_SUBAGENT_INDEX_LOCK:
        indexed_session_id = CODEX_SUBAGENT_SESSION_INDEX.get(thread_id)
        generation = CODEX_SUBAGENT_LIVE_GENERATIONS.get(thread_id)
    session_id = str(
        state.get("session_id") or indexed_session_id or ""
    ).strip()
    if session_id and session_id in BUSY_SESSIONS:
        owner = ACTIVE.get(session_id) or CURRENT_TURNS.get(session_id) or {}
        state_run_id = str(state.get("run_id") or "").strip()
        owner_run_id = str(owner.get("run_id") or "").strip()
        if not state_run_id or not owner_run_id or state_run_id == owner_run_id:
            return True

    manager = CODEX_APP_SERVER_MANAGER
    if manager is None:
        return False
    with suppress(Exception):
        if manager.active_turn(thread_id) is not None:
            return True
    return bool(
        generation is not None
        and getattr(manager, "ready", False) is True
        and getattr(manager, "generation", None) == generation
    )


def active_codex_work_labels() -> list[str]:
    labels: set[str] = set()
    for session_id in BUSY_SESSIONS:
        current = CURRENT_TURNS.get(session_id) or {}
        active = ACTIVE.get(session_id) or {}
        session = STORE.sessions.get(session_id) or {}
        backend = str(
            active.get("backend")
            or current.get("backend")
            or session.get("backend")
            or DEFAULT_BACKEND
        ).strip().lower()
        if backend == BACKEND_CODEX:
            labels.add(f"active chat {session_id}")
    for session_id in SERVER_MAINTENANCE_SESSIONS:
        session = STORE.sessions.get(session_id) or {}
        if str(session.get("backend") or DEFAULT_BACKEND).lower() == BACKEND_CODEX:
            labels.add(f"Codex maintenance for {session_id}")
    for (session_id, operation_id), task in CODEX_NATIVE_ACTION_TASKS.items():
        if not task.done():
            labels.add(f"Codex operation {operation_id} in {session_id}")
    for pending in CODEX_PENDING_INTERACTIONS.values():
        session_id = str(pending.get("session_id") or "unknown")
        labels.add(f"Codex prompt in {session_id}")
    with CODEX_SUBAGENT_INDEX_LOCK:
        codex_subagent_states = [
            (thread_id, dict(state))
            for thread_id, state in CODEX_SUBAGENT_STATE.items()
        ]
    for thread_id, state in codex_subagent_states:
        if codex_subagent_has_live_owner(thread_id, state):
            labels.add(f"Codex subagent {thread_id}")
    return sorted(labels)


SERVER_UPDATE_PROVIDER_WORK_LABEL_LIMIT = 32
MAX_CLAUDE_BACKGROUND_EVENT_SCAN_BYTES = 64 * 1024 * 1024
CLAUDE_PROVIDER_INSPECTION_OVERFLOW_LABEL = (
    "Claude provider state exceeds safe inspection limit"
)
CLAUDE_BACKGROUND_WORK_CACHE_KEY: tuple[Any, ...] | None = None
CLAUDE_BACKGROUND_WORK_CACHE_LABELS: tuple[str, ...] = ()


def loaded_claude_background_session_state(
    manager: Any,
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    """Capture bounded loaded Claude ownership without missing overflow work.

    Event folding is intentionally capped, but the cap must not make a loaded
    supervisor beyond the first page invisible. Once more loaded sessions
    exist than can be inspected, retain a conservative blocker instead of
    treating the uninspected suffix as idle.
    """

    if manager is None:
        return (), ()
    loaded_session_ids: list[str] = []
    unknown_labels: list[str] = []
    for session_id, session in tuple(STORE.sessions.items()):
        if (
            str(session.get("backend") or DEFAULT_BACKEND).strip().lower()
            != BACKEND_CLAUDE
            or session_id in BUSY_SESSIONS
            or session_id in SERVER_MAINTENANCE_SESSIONS
        ):
            continue
        try:
            loaded = manager.is_loaded(session_id)
        except Exception:
            if len(unknown_labels) < SERVER_UPDATE_PROVIDER_WORK_LABEL_LIMIT:
                unknown_labels.append(
                    f"Claude provider state unknown in {session_id}"
                )
            continue
        if loaded:
            if len(loaded_session_ids) < SERVER_UPDATE_PROVIDER_WORK_LABEL_LIMIT:
                loaded_session_ids.append(session_id)
                continue
            # Scanning arbitrary numbers of histories makes restart/update
            # admission unbounded. One extra loaded supervisor is sufficient
            # proof that the capped scan cannot establish an idle state.
            if len(unknown_labels) < SERVER_UPDATE_PROVIDER_WORK_LABEL_LIMIT:
                unknown_labels.append(
                    CLAUDE_PROVIDER_INSPECTION_OVERFLOW_LABEL
                )
            elif unknown_labels:
                # Existing unknown labels already fail closed, but use a
                # stable overflow marker so revalidation records why the
                # enumeration stopped.
                unknown_labels[-1] = CLAUDE_PROVIDER_INSPECTION_OVERFLOW_LABEL
            break
    return tuple(loaded_session_ids), tuple(unknown_labels)


def claude_event_file_fingerprints(
    session_ids: tuple[str, ...],
) -> tuple[tuple[Any, ...], ...]:
    """Return bounded metadata proving the scanned event inputs are unchanged."""

    fingerprints: list[tuple[Any, ...]] = []
    for session_id in session_ids:
        try:
            stat = events_path(session_id).stat()
        except FileNotFoundError:
            fingerprints.append((session_id, "missing"))
        except OSError:
            fingerprints.append((session_id, "unreadable"))
        else:
            fingerprints.append((
                session_id,
                "file",
                int(stat.st_dev),
                int(stat.st_ino),
                int(stat.st_size),
                int(stat.st_mtime_ns),
                int(stat.st_ctime_ns),
            ))
    return tuple(fingerprints)


def active_provider_background_work_labels() -> list[str]:
    """Return bounded provider-owned work that survives its parent turn.

    The managed updater already excludes active and queued parent turns. Codex
    can additionally own native operations and live child threads, while a
    loaded Claude SDK supervisor can retain background subagents after its
    parent ResultMessage. Only loaded Claude supervisors are considered: event
    history alone must never turn into a permanent update blocker after the
    provider process has been evicted or the server has restarted.
    """

    labels = active_codex_work_labels()[:SERVER_UPDATE_PROVIDER_WORK_LABEL_LIMIT]
    remaining = SERVER_UPDATE_PROVIDER_WORK_LABEL_LIMIT - len(labels)
    manager = CLAUDE_SDK_MANAGER
    if remaining <= 0 or manager is None:
        return labels

    for session_id, session in tuple(STORE.sessions.items()):
        if remaining <= 0:
            break
        if (
            str(session.get("backend") or DEFAULT_BACKEND).strip().lower()
            != BACKEND_CLAUDE
            or session_id in BUSY_SESSIONS
            or session_id in SERVER_MAINTENANCE_SESSIONS
        ):
            continue
        try:
            loaded = manager.is_loaded(session_id)
        except Exception:
            # Failure to inspect a live supervisor is not proof that it is safe
            # to terminate. Fail closed and require an explicit retry/update.
            labels.append(f"Claude provider state unknown in {session_id}")
            remaining -= 1
            continue
        if not loaded:
            continue
        claude_labels = claude_background_work_labels_from_events((session_id,))
        if claude_labels:
            labels.extend(claude_labels[:remaining])
            remaining -= 1
    return labels


def claude_background_work_labels_from_events(
    session_ids: tuple[str, ...],
) -> list[str]:
    """Inspect bounded durable Claude child state off the asyncio thread."""

    labels: list[str] = []
    for session_id in session_ids:
        try:
            event_bytes = events_path(session_id).stat().st_size
        except FileNotFoundError:
            event_bytes = 0
        except OSError:
            labels.append(f"Claude provider state unknown in {session_id}")
            continue
        if event_bytes > MAX_CLAUDE_BACKGROUND_EVENT_SCAN_BYTES:
            # Never make restart/update admission parse an arbitrarily large
            # transcript. Failing closed is safe and the operator can Stop the
            # loaded chat (which evicts its provider supervisor) before retry.
            labels.append(f"Claude provider state too large in {session_id}")
            continue
        try:
            snapshot = build_claude_subagent_snapshot(session_id, limit=1)
            active_count = max(0, int(snapshot.get("active_count") or 0))
        except Exception:
            # A loaded provider process whose durable child state cannot be
            # inspected is not proof that it is safe to terminate.
            active_count = 1
        if active_count:
            labels.append(f"Claude background work in {session_id}")
    return labels


async def prepare_provider_background_work_snapshot(
    *,
    timeout_seconds: float | None = None,
) -> dict[str, Any]:
    """Fold Claude events before admission locks and bind them to metadata."""

    global CLAUDE_BACKGROUND_WORK_CACHE_KEY
    global CLAUDE_BACKGROUND_WORK_CACHE_LABELS

    manager = CLAUDE_SDK_MANAGER
    session_ids, unknown_labels = loaded_claude_background_session_state(manager)
    fingerprints_before = await asyncio.to_thread(
        claude_event_file_fingerprints,
        session_ids,
    )
    cache_key = (id(manager), session_ids, fingerprints_before)
    if CLAUDE_BACKGROUND_WORK_CACHE_KEY == cache_key:
        claude_labels = list(CLAUDE_BACKGROUND_WORK_CACHE_LABELS)
    else:
        scan_task = asyncio.create_task(
            asyncio.to_thread(
                claude_background_work_labels_from_events,
                session_ids,
            )
        )
        try:
            if timeout_seconds is None:
                claude_labels = await scan_task
            else:
                claude_labels = await asyncio.wait_for(
                    asyncio.shield(scan_task),
                    timeout=max(0.0, float(timeout_seconds)),
                )
        except (TimeoutError, asyncio.TimeoutError):
            scan_task.add_done_callback(
                lambda done: (
                    done.exception() if not done.cancelled() else None
                )
            )
            return {
                "manager": manager,
                "session_ids": session_ids,
                "unknown_labels": unknown_labels,
                "fingerprints": fingerprints_before,
                "claude_labels": (),
                "consistent": False,
                "error": "timeout",
            }
        except Exception:
            return {
                "manager": manager,
                "session_ids": session_ids,
                "unknown_labels": unknown_labels,
                "fingerprints": fingerprints_before,
                "claude_labels": (),
                "consistent": False,
                "error": "scan_failed",
            }

    fingerprints_after = await asyncio.to_thread(
        claude_event_file_fingerprints,
        session_ids,
    )
    consistent = fingerprints_before == fingerprints_after
    if consistent:
        CLAUDE_BACKGROUND_WORK_CACHE_KEY = cache_key
        CLAUDE_BACKGROUND_WORK_CACHE_LABELS = tuple(claude_labels)
    return {
        "manager": manager,
        "session_ids": session_ids,
        "unknown_labels": unknown_labels,
        "fingerprints": fingerprints_after,
        "claude_labels": tuple(claude_labels),
        "consistent": consistent,
        "error": None if consistent else "events_changed",
    }


def provider_background_work_labels_from_snapshot(
    snapshot: dict[str, Any],
) -> list[str]:
    """Validate a pre-lock fold using bounded process state and stat calls."""

    labels = active_codex_work_labels()[:SERVER_UPDATE_PROVIDER_WORK_LABEL_LIMIT]
    remaining = SERVER_UPDATE_PROVIDER_WORK_LABEL_LIMIT - len(labels)
    if remaining <= 0:
        return labels

    manager = CLAUDE_SDK_MANAGER
    session_ids, unknown_labels = loaded_claude_background_session_state(manager)
    fingerprints = claude_event_file_fingerprints(session_ids)
    snapshot_is_current = (
        snapshot.get("consistent") is True
        and manager is snapshot.get("manager")
        and session_ids == tuple(snapshot.get("session_ids") or ())
        and unknown_labels == tuple(snapshot.get("unknown_labels") or ())
        and fingerprints == tuple(snapshot.get("fingerprints") or ())
    )
    if not snapshot_is_current:
        snapshot["stale"] = True
        labels.append("Claude provider state changed during inspection")
        return labels[:SERVER_UPDATE_PROVIDER_WORK_LABEL_LIMIT]

    labels.extend(unknown_labels[:remaining])
    remaining = SERVER_UPDATE_PROVIDER_WORK_LABEL_LIMIT - len(labels)
    if remaining > 0:
        labels.extend(
            list(snapshot.get("claude_labels") or ())[:remaining]
        )
    return labels


async def active_provider_background_work_labels_async() -> list[str]:
    """Return bounded provider blockers without scanning on the event loop."""

    snapshot = await prepare_provider_background_work_snapshot()
    return provider_background_work_labels_from_snapshot(snapshot)


async def reserve_codex_goals_reconfiguration() -> None:
    """Close Codex admission and reject a setting change if work exists."""

    global CODEX_GOALS_RECONFIGURING
    async with ACTIVE_LOCK:
        update_blocker = managed_server_update_admission_blocker()
        if update_blocker:
            raise HTTPException(status_code=503, detail=update_blocker)
        if CODEX_GOALS_RECONFIGURING:
            raise HTTPException(
                status_code=409,
                detail="Codex goals configuration is already changing",
            )
        CODEX_GOALS_RECONFIGURING = True
        active_labels = active_codex_work_labels()
    try:
        async with QUEUE_LOCK:
            queued_labels = [
                f"queued Codex turn {item.get('queued_id') or 'unknown'} in {session_id}"
                for session_id, queue in QUEUED_TURNS.items()
                for item in queue
                if queued_turn_backend(session_id, item) == BACKEND_CODEX
            ]
            for session_id, item in RUN_NOW_TURNS.items():
                if queued_turn_backend(session_id, item) == BACKEND_CODEX:
                    queued_labels.append(f"queued Codex Force Send in {session_id}")
        blockers = [*active_labels, *queued_labels]
        if blockers:
            preview = ", ".join(blockers[:3])
            remainder = len(blockers) - min(3, len(blockers))
            if remainder:
                preview += f", and {remainder} more"
            raise HTTPException(
                status_code=409,
                detail=(
                    "Codex goals cannot be reconfigured while Codex work is "
                    f"active or queued: {preview}"
                ),
            )
    except BaseException:
        async with ACTIVE_LOCK:
            CODEX_GOALS_RECONFIGURING = False
        raise


async def release_codex_goals_reconfiguration() -> None:
    global CODEX_GOALS_RECONFIGURING
    async with ACTIVE_LOCK:
        CODEX_GOALS_RECONFIGURING = False


async def pause_idle_codex_goals_before_disable() -> dict[str, int]:
    paused = 0
    fenced = 0
    manager = CODEX_APP_SERVER_MANAGER

    def loaded_provider_goal_may_exist(session: dict[str, Any]) -> bool:
        thread_id = str(session_provider_id(session) or "").strip()
        return bool(
            manager is not None
            and thread_id
            and manager.is_thread_loaded(thread_id)
        )

    candidates = [
        session_id
        for session_id, session in list(STORE.sessions.items())
        if str(session.get("backend") or DEFAULT_BACKEND).lower() == BACKEND_CODEX
        and (
            isinstance(session.get("codex_goal"), dict)
            or bool(session.get("_codex_goal_reconciliation_required"))
            or loaded_provider_goal_may_exist(session)
        )
    ]
    for session_id in candidates:
        async with session_lifecycle_lock(session_id):
            if (
                session_id in DELETING_SESSIONS
                or session_id not in STORE.sessions
            ):
                continue
            result = await settle_idle_codex_goal_for_stop(session_id)
            if result.get("goal_paused"):
                paused += 1
            if result.get("goal_fenced"):
                fenced += 1
            current_goal = (STORE.sessions.get(session_id) or {}).get("codex_goal")
            if (
                isinstance(current_goal, dict)
                and str(current_goal.get("status") or "").lower() == "active"
            ):
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Could not safely pause the active Codex goal in "
                        f"{session_id}; retry after stopping that chat"
                    ),
                )
    return {"paused_goal_count": paused, "fenced_goal_count": fenced}


async def get_codex_goals_admin() -> dict[str, Any]:
    return codex_goals_admin_status()


async def put_codex_goals_admin(
    req: CodexGoalsAdminRequest,
) -> dict[str, Any]:
    global CODEX_GOALS_ENABLED
    async with CODEX_GOALS_CONFIG_LOCK:
        requested = bool(req.enabled)
        if requested == CODEX_GOALS_ENABLED:
            return codex_goals_admin_status()
        await reserve_codex_goals_reconfiguration()
        transition: dict[str, int] = {
            "paused_goal_count": 0,
            "fenced_goal_count": 0,
        }
        try:
            if not requested:
                transition = await pause_idle_codex_goals_before_disable()
            # The feature flag is a process-level Codex setting. Replacing the
            # shared, idle manager is the only way to make it authoritative for
            # every loaded and future thread.
            await close_codex_app_server_manager()
            atomic_update_json(
                CODEX_SETTINGS_FILE,
                {
                    "goals_enabled": requested,
                    "updated_at": update_utc_now(),
                },
            )
            CODEX_GOALS_ENABLED = requested
        finally:
            await release_codex_goals_reconfiguration()
        return {**codex_goals_admin_status(), **transition}


def require_native_admin_control(request: Request) -> None:
    """Repeat privileged native auth at the endpoint invocation boundary."""

    if privileged_native_browser_request_forbidden(request):
        raise HTTPException(status_code=403, detail="forbidden")
    if not AGENT_TOKEN:
        raise HTTPException(
            status_code=503,
            detail=(
                "This administrative control requires authenticated "
                "AgentsServer mode"
            ),
        )
    if not request_exact_native_token_header_authorized(request):
        raise HTTPException(status_code=401, detail="unauthorized")


@app.get("/api/admin/codex/goals")
async def get_codex_goals_admin_endpoint(request: Request) -> dict[str, Any]:
    require_native_admin_control(request)
    return await get_codex_goals_admin()


@app.put("/api/admin/codex/goals")
async def put_codex_goals_admin_endpoint(
    req: CodexGoalsAdminRequest,
    request: Request,
) -> dict[str, Any]:
    require_native_admin_control(request)
    return await put_codex_goals_admin(req)


def require_team_hub_bootstrap_control(
    request: Request,
) -> tuple[str, str | None]:
    if team_hub_bootstrap_browser_request_forbidden(request):
        raise HTTPException(status_code=403, detail="forbidden")
    if not AGENT_TOKEN:
        raise HTTPException(
            status_code=503,
            detail="Team Hub bootstrap proof issuance requires authenticated AgentsServer mode",
        )
    if not request_exact_bearer_authorized(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    identity = TEAM_HUB_RUNTIME.tailscale_serve_identity(request)
    if identity is not None and identity.tailnet_login is not None:
        return "tailscale_serve", identity.tailnet_login
    identity = TEAM_HUB_RUNTIME.direct_ip_identity(request)
    if identity is None:
        raise HTTPException(
            status_code=403,
            detail=(
                "Team Hub bootstrap proof issuance requires an exact configured "
                "remote Teamspace transport"
            ),
        )
    return "direct_ip", None


def team_hub_capability_has_route(
    capability: dict[str, Any],
    transport: str,
    hub_url: str,
) -> bool:
    routes = capability.get("routes")
    if isinstance(routes, list):
        return any(
            isinstance(route, dict)
            and route.get("transport") == transport
            and route.get("hub_url") == hub_url
            for route in routes
        )
    return (
        capability.get("transport") == transport
        and capability.get("hub_url") == hub_url
    )


@app.post("/api/admin/team-hub/bootstrap-proof")
async def team_hub_bootstrap_proof_endpoint(
    body: TeamHubBootstrapProofRequest,
    request: Request,
) -> Response:
    request_transport, tailnet_login = require_team_hub_bootstrap_control(request)
    capability = TEAM_HUB_RUNTIME.capability()
    expected_transport = body.expected_transport or "tailscale_serve"
    if (
        not capability.get("available")
        or request_transport != expected_transport
        or not team_hub_capability_has_route(
            capability,
            expected_transport,
            body.expected_hub_url,
        )
        or (
            expected_transport == "direct_ip"
            and body.unsafe_direct_ip_confirmed is not True
        )
        or (
            expected_transport == "tailscale_serve"
            and body.unsafe_direct_ip_confirmed is not None
        )
        or str(capability.get("host_server_identity") or "")
        != body.expected_server_identity
        or SERVER_INSTANCE_ID != body.expected_server_instance_id
        or str(capability.get("hub_id") or "") != body.expected_hub_id
    ):
        raise HTTPException(
            status_code=409,
            detail="The designated Team Hub host changed before confirmation",
        )
    try:
        result = await TEAM_HUB_RUNTIME.issue_tailnet_bootstrap_proof(
            request_id=str(body.request_id),
            server_identity=body.expected_server_identity,
            server_instance_id=body.expected_server_instance_id,
            hub_url=body.expected_hub_url,
            tailnet_login=(
                tailnet_login
                if expected_transport == "tailscale_serve"
                else body.recipient_email
            ),
            recipient_email=body.recipient_email,
            display_name=body.display_name,
            device_label=body.device_label,
            transport=expected_transport,
        )
    except HubError as exc:
        return JSONResponse(
            status_code=exc.status_code,
            content={"error": {"code": exc.code, "message": exc.message}},
            headers={"Cache-Control": "no-store", "Pragma": "no-cache"},
        )
    return JSONResponse(
        content=result,
        headers={"Cache-Control": "no-store", "Pragma": "no-cache"},
    )


def require_server_restart_control(request: Request) -> None:
    if server_restart_browser_request_forbidden(request):
        raise HTTPException(status_code=403, detail="forbidden")
    if not AGENT_TOKEN:
        raise HTTPException(
            status_code=503,
            detail=server_restart_error_detail(
                "server_restart_auth_required",
                "Server restart requires authenticated AgentsServer mode.",
                action="Install or configure AgentsServer with an access token.",
            ),
        )
    if not request_exact_restart_header_authorized(request):
        raise HTTPException(
            status_code=401,
            detail=server_restart_error_detail(
                "server_restart_unauthorized",
                "Server restart requires an access token in an authorization header.",
            ),
        )
    # Cached positive proof: the managed-service probe runs a subprocess and
    # must not be repeated (or time out into a refusal) on the emergency path.
    if managed_server_service_kind() is None:
        raise HTTPException(
            status_code=503,
            detail=server_restart_error_detail(
                "server_restart_unmanaged",
                "Server restart is unavailable for an unmanaged server process.",
                action="Install AgentsServer as its supported user service, then reconnect.",
            ),
        )


def signal_forced_server_restart(request_id: str) -> None:
    """Signal an emergency restart without depending on the restart journal.

    Runs on a dedicated thread after the accepted response has had time to
    flush. Unlike the cooperative path, a journal that cannot be read or
    written, a superseding record, or a wedged event loop cannot stop this
    worker: it arms the hard-kill watchdog first and then sends SIGTERM to
    this process so the managed user service relaunches it.
    """

    time.sleep(SERVER_RESTART_SIGNAL_DELAY_SECONDS)
    pid = os.getpid()
    with SERVER_RESTART_SIGNAL_LOCK:
        try:
            status = read_server_restart_status()
            if (
                str(status.get("request_id") or "") == request_id
                and str(status.get("phase") or "") == "signaling"
            ):
                # A duplicate worker for the same request already signaled;
                # its watchdog owns the hard kill.
                return
        except Exception:
            status = {}
        with suppress(Exception):
            write_server_restart_status(
                phase="signaling",
                request_id=request_id,
                _source_instance_id=SERVER_INSTANCE_ID,
                _forced=True,
                message=(
                    "AgentsServer is force restarting; reconnecting clients "
                    "will briefly go offline."
                ),
            )
        threading.Thread(
            target=force_kill_managed_server_after_deadline,
            args=(request_id, pid),
            daemon=True,
            name="agents-server-force-restart",
        ).start()
        with suppress(Exception):
            os.kill(pid, signal.SIGTERM)


def start_forced_server_restart_signal_thread(request_id: str) -> None:
    threading.Thread(
        target=signal_forced_server_restart,
        args=(request_id,),
        daemon=True,
        name="agents-server-forced-restart-signal",
    ).start()


async def forced_server_restart_team_hub_snapshot_attempt() -> bool:
    """Best-effort Hub snapshot plus reopen for the emergency restart path."""

    snapshot_succeeded = False
    try:
        await TEAM_HUB_RUNTIME.prepare_maintenance(
            "server-restart",
            persistent_fence=False,
            allow_unavailable_host=True,
        )
        snapshot_succeeded = True
    except Exception:
        pass
    try:
        # This follows snapshot settlement, never its deadline. A late native
        # snapshot worker therefore cannot close admission after this reopen.
        await TEAM_HUB_RUNTIME.reopen_admission()
    except Exception:
        return False
    return snapshot_succeeded


def retain_forced_server_restart_hub_straggler(
    task: asyncio.Task[Any],
    request_id: str,
) -> None:
    """Retain and consume a Hub attempt that outlived the emergency deadline."""

    SERVER_RESTART_FORCE_HUB_STRAGGLERS.add(task)

    def settled(completed: asyncio.Task[Any]) -> None:
        SERVER_RESTART_FORCE_HUB_STRAGGLERS.discard(completed)
        try:
            succeeded = completed.result()
        except BaseException as exc:
            logger.warning(
                "late forced-restart Team Hub settlement failed "
                "request_id=%s error_type=%s",
                request_id,
                type(exc).__name__,
            )
            return
        if succeeded is not True:
            logger.warning(
                "late forced-restart Team Hub snapshot was skipped request_id=%s",
                request_id,
            )

    task.add_done_callback(settled)


async def accept_forced_server_restart(
    body: ServerRestartRequest,
    *,
    request_id: str,
    request_fingerprint: str,
) -> dict[str, Any]:
    """Accept an emergency restart without refusing or waiting on server state.

    Guarantees for ``force: true`` + ``force_confirmed: true``:

    * Only header authentication, the managed-service proof (both already
      checked by ``require_server_restart_control``) and the exact target
      identity/instance are required.
    * Everything the cooperative path refuses on is audited instead: the
      restart cooldown, a pending or stale restart record, an active managed
      update, safety-critical work (maintenance, deletions, HTTP mutations,
      goal reconfiguration), a stale or omitted blocker revision, and a Team
      Hub snapshot failure.
    * No lock or probe is awaited beyond its bounded timeout; a wedged lock
      degrades the audit snapshot rather than hanging the request.
    * The journal is best effort: if it cannot be written the restart still
      proceeds, because the journal exists to explain the restart, not to
      authorize it.
    * SIGTERM is sent from a dedicated thread and a hard-kill watchdog
      guarantees the process exits even when graceful shutdown hangs.
    """

    if (
        body.expected_server_identity != server_identity()
        or body.expected_server_instance_id != SERVER_INSTANCE_ID
    ):
        raise HTTPException(
            status_code=409,
            detail=server_restart_error_detail(
                "server_restart_target_changed",
                "The connected AgentsServer instance changed before restart confirmation.",
                action="Refresh the server connection and confirm the restart again.",
                retryable=True,
            ),
        )

    audit: dict[str, Any] = {}
    degraded_reasons: list[str] = []
    async with bounded_lock(
        SERVER_UPDATE_OPERATION_LOCK,
        SERVER_RESTART_FORCE_LOCK_TIMEOUT_SECONDS,
    ) as operation_lock_held:
        if not operation_lock_held:
            degraded_reasons.append("update_operation_lock")
        try:
            restart_status = reconcile_stale_server_restart_acceptance()
        except Exception:
            restart_status = {"phase": "idle"}
            degraded_reasons.append("restart_journal_unreadable")
        if str(restart_status.get("request_id") or "") == request_id:
            accepted_fingerprint = str(
                restart_status.get("_request_fingerprint") or ""
            )
            if not accepted_fingerprint or not hmac.compare_digest(
                accepted_fingerprint,
                request_fingerprint,
            ):
                raise HTTPException(
                    status_code=409,
                    detail=server_restart_error_detail(
                        "server_restart_request_changed",
                        "The restart request ID was already used with different confirmation details.",
                        action=(
                            "Refresh the server connection and use a new request ID "
                            "for a newly confirmed restart."
                        ),
                    ),
                )
            if (
                str(restart_status.get("phase") or "") == "accepted"
                and str(restart_status.get("_source_instance_id") or "")
                == SERVER_INSTANCE_ID
            ):
                start_forced_server_restart_signal_thread(request_id)
            return public_server_restart_status(restart_status)

        phase = str(restart_status.get("phase") or "")
        if phase in SERVER_RESTART_ACTIVE_PHASES:
            audit["superseded_pending_restart"] = True
        elif (
            phase in {"complete", "failed"}
            and server_restart_status_age_seconds(restart_status)
            < SERVER_RESTART_COOLDOWN_SECONDS
        ):
            audit["cooldown_overridden"] = True
        try:
            update_status = read_server_update_status()
        except Exception:
            update_status = {}
        if managed_server_update_blocks_work(update_status):
            audit["update_in_progress_overridden"] = True
            audit["update_phase"] = str(update_status.get("phase") or "")

        snapshot = await current_server_restart_blocker_snapshot(
            lock_timeout_seconds=SERVER_RESTART_FORCE_LOCK_TIMEOUT_SECONDS,
        )
        if snapshot.get("snapshot_degraded") is True:
            degraded_reasons.extend(
                str(reason)
                for reason in snapshot.get("snapshot_degraded_reasons") or ()
            )
        if body.expected_blocker_revision is None:
            audit["blocker_revision_omitted"] = True
        elif not hmac.compare_digest(
            str(body.expected_blocker_revision),
            str(snapshot.get("revision") or ""),
        ):
            audit["blockers_changed_after_confirmation"] = True
        if snapshot.get("has_safety_blockers") is True:
            audit["safety_blockers_overridden"] = True
        if degraded_reasons:
            audit["snapshot_degraded"] = True
            audit["snapshot_degraded_reasons"] = degraded_reasons

        hub_attempt = asyncio.create_task(
            forced_server_restart_team_hub_snapshot_attempt(),
            name=f"forced-restart-team-hub-{request_id}",
        )
        try:
            completed, _pending = await asyncio.wait(
                {hub_attempt},
                timeout=SERVER_RESTART_FORCE_HUB_SNAPSHOT_TIMEOUT_SECONDS,
            )
        except asyncio.CancelledError:
            retain_forced_server_restart_hub_straggler(
                hub_attempt,
                request_id,
            )
            raise
        if hub_attempt not in completed:
            audit["team_hub_snapshot_skipped"] = True
            retain_forced_server_restart_hub_straggler(
                hub_attempt,
                request_id,
            )
        else:
            try:
                hub_snapshot_succeeded = hub_attempt.result()
            except BaseException:
                hub_snapshot_succeeded = False
            if hub_snapshot_succeeded is not True:
                audit["team_hub_snapshot_skipped"] = True

        now = update_utc_now()
        journal_changes: dict[str, Any] = dict(
            phase="accepted",
            request_id=request_id,
            _source_instance_id=SERVER_INSTANCE_ID,
            _request_fingerprint=request_fingerprint,
            _forced=True,
            _forced_work_snapshot=public_server_restart_work_counts(snapshot),
            _forced_audit=audit,
            message=(
                "AgentsServer accepted the forced restart; any active work "
                "will be interrupted while its user service relaunches."
            ),
            requested_at=now,
            completed_at=None,
            failed_at=None,
        )
        try:
            restart_status = write_server_restart_status(**journal_changes)
        except Exception as exc:
            logger.error(
                "forced restart journal could not be written; restarting anyway "
                "request_id=%s error_type=%s",
                request_id,
                type(exc).__name__,
            )
            restart_status = {**journal_changes, "updated_at": now}
    logger.warning(
        "forced server restart accepted request_id=%s audit=%s",
        request_id,
        json.dumps(public_forced_restart_audit(audit), sort_keys=True),
    )
    start_forced_server_restart_signal_thread(request_id)
    return public_server_restart_status(restart_status)


@app.get("/api/admin/restart")
async def server_restart_status_endpoint(request: Request) -> dict[str, Any]:
    require_server_restart_control(request)
    blocker_snapshot = await current_server_restart_blocker_snapshot()
    return public_server_restart_status(
        blocker_snapshot=blocker_snapshot,
    )


def log_server_restart_denial(
    body: ServerRestartRequest,
    exc: HTTPException,
) -> None:
    """Record why a restart was refused; clients rarely surface the detail."""

    detail = exc.detail if isinstance(exc.detail, dict) else {"message": str(exc.detail)}
    snapshot = detail.get("blocker_snapshot")
    counts = (
        public_server_restart_work_counts(snapshot)
        if isinstance(snapshot, dict)
        else {}
    )
    logger.warning(
        "server restart denied status=%s code=%s forced=%s message=%s blockers=%s",
        exc.status_code,
        str(detail.get("code") or "")[:64],
        body.force is True and body.force_confirmed is True,
        str(detail.get("message") or "")[:200],
        json.dumps(counts, sort_keys=True),
    )


@app.post("/api/admin/restart", status_code=202)
async def restart_server_endpoint(
    body: ServerRestartRequest,
    request: Request,
    background_tasks: BackgroundTasks,
) -> dict[str, Any]:
    try:
        return await _restart_server_endpoint_impl(
            body,
            request,
            background_tasks,
        )
    except HTTPException as exc:
        log_server_restart_denial(body, exc)
        raise


async def _restart_server_endpoint_impl(
    body: ServerRestartRequest,
    request: Request,
    background_tasks: BackgroundTasks,
) -> dict[str, Any]:
    require_server_restart_control(request)
    request_id = str(body.request_id)
    forced = body.force is True and body.force_confirmed is True
    request_fingerprint = server_restart_request_fingerprint(body)

    if forced:
        # Emergency path: never refuse or hang on server state. See
        # accept_forced_server_restart for the exact guarantees.
        return await accept_forced_server_restart(
            body,
            request_id=request_id,
            request_fingerprint=request_fingerprint,
        )

    async with SERVER_UPDATE_OPERATION_LOCK:
        restart_status = reconcile_stale_server_restart_acceptance()
        if str(restart_status.get("request_id") or "") == request_id:
            accepted_fingerprint = str(
                restart_status.get("_request_fingerprint") or ""
            )
            if not accepted_fingerprint or not hmac.compare_digest(
                accepted_fingerprint,
                request_fingerprint,
            ):
                raise HTTPException(
                    status_code=409,
                    detail=server_restart_error_detail(
                        "server_restart_request_changed",
                        "The restart request ID was already used with different confirmation details.",
                        action=(
                            "Refresh the server connection and use a new request ID "
                            "for a newly confirmed restart."
                        ),
                    ),
                )
            if (
                str(restart_status.get("phase") or "") == "accepted"
                and str(restart_status.get("_source_instance_id") or "")
                == SERVER_INSTANCE_ID
            ):
                background_tasks.add_task(
                    signal_managed_server_restart,
                    request_id,
                )
            return public_server_restart_status(restart_status)
        if managed_server_restart_blocks_work(restart_status):
            raise HTTPException(
                status_code=409,
                detail=server_restart_error_detail(
                    "server_restart_in_progress",
                    "Another AgentsServer restart is already in progress.",
                    action="Wait for the server to reconnect before retrying.",
                    retryable=True,
                ),
            )
        terminal_restart = str(restart_status.get("phase") or "") in {
            "complete",
            "failed",
        }
        cooldown_remaining = (
            max(
                0,
                math.ceil(
                    SERVER_RESTART_COOLDOWN_SECONDS
                    - server_restart_status_age_seconds(restart_status)
                ),
            )
            if terminal_restart
            else 0
        )
        if terminal_restart and cooldown_remaining > 0:
            raise HTTPException(
                status_code=409,
                detail=server_restart_error_detail(
                    "server_restart_cooldown",
                    "AgentsServer was restarted recently.",
                    action="Wait briefly before requesting another restart.",
                    retryable=True,
                    retry_after_seconds=cooldown_remaining,
                ),
            )

        current_server_identity = server_identity()
        if (
            body.expected_server_identity != current_server_identity
            or body.expected_server_instance_id != SERVER_INSTANCE_ID
        ):
            raise HTTPException(
                status_code=409,
                detail=server_restart_error_detail(
                    "server_restart_target_changed",
                    "The connected AgentsServer instance changed before restart confirmation.",
                    action="Refresh the server connection and confirm the restart again.",
                    retryable=True,
                ),
            )
        if managed_server_service_kind() is None:
            raise HTTPException(
                status_code=503,
                detail=server_restart_error_detail(
                    "server_restart_unmanaged",
                    "Managed service ownership changed before restart acceptance.",
                    action="Reconnect or reinstall the supported AgentsServer user service.",
                ),
            )
        if managed_server_update_blocks_work():
            raise HTTPException(
                status_code=409,
                detail=server_restart_error_detail(
                    "server_update_in_progress",
                    "AgentsServer cannot restart while a managed update is in progress.",
                    action="Wait for the update to finish, then retry.",
                    retryable=True,
                ),
            )

        # Folding a long Claude event history is disk/JSON work. Complete it
        # before closing global admission, then validate cheap file metadata
        # under the locks so a concurrent provider change fails closed.
        provider_work_snapshot = (
            await prepare_provider_background_work_snapshot()
        )
        async with ACTIVE_LOCK:
            async with QUEUE_LOCK:
                async with UNSAFE_HTTP_MUTATION_ADMISSION_LOCK:
                    # Recheck every fence while holding the same locks used by
                    # turn/queue and HTTP-mutation admission. Once the journal
                    # is accepted, no new work can enter before SIGTERM.
                    restart_status = reconcile_stale_server_restart_acceptance()
                    if managed_server_restart_blocks_work(restart_status):
                        raise HTTPException(
                            status_code=409,
                            detail=server_restart_error_detail(
                                "server_restart_in_progress",
                                "Another AgentsServer restart is already in progress.",
                                action="Wait for the server to reconnect before retrying.",
                                retryable=True,
                            ),
                        )
                    if managed_server_update_blocks_work():
                        raise HTTPException(
                            status_code=409,
                            detail=server_restart_error_detail(
                                "server_update_in_progress",
                                "AgentsServer cannot restart while a managed update is in progress.",
                                action="Wait for the update to finish, then retry.",
                                retryable=True,
                            ),
                        )
                    tmux_cgroup_state = await asyncio.to_thread(
                        server_restart_tmux_cgroup_state
                    )
                    provider_work_labels = (
                        provider_background_work_labels_from_snapshot(
                            provider_work_snapshot
                        )
                    )
                    blocker_snapshot = server_restart_blocker_snapshot_locked(
                        tmux_cgroup_state=tmux_cgroup_state,
                        provider_background_work_labels=provider_work_labels,
                    )
                    active_count = int(blocker_snapshot["active_count"])
                    queued_count = int(
                        blocker_snapshot["restart_blocking_queued_count"]
                    )
                    provider_count = int(
                        blocker_snapshot["provider_background_count"]
                    )
                    maintenance_count = int(
                        blocker_snapshot["server_maintenance_count"]
                    )
                    mutation_count = int(blocker_snapshot["mutation_count"])
                    deleting_count = int(
                        blocker_snapshot["deleting_session_count"]
                    )
                    codex_goals_reconfiguring = bool(
                        blocker_snapshot["codex_goals_reconfiguring"]
                    )
                    if forced and not hmac.compare_digest(
                        str(body.expected_blocker_revision or ""),
                        str(blocker_snapshot["revision"]),
                    ):
                        raise HTTPException(
                            status_code=409,
                            detail=server_restart_error_detail(
                                "server_restart_blockers_changed",
                                "Server work changed after force restart was confirmed.",
                                action=(
                                    "Review the refreshed blocker counts and confirm "
                                    "force restart again."
                                ),
                                retryable=True,
                                blocker_snapshot=blocker_snapshot,
                            ),
                        )
                    if blocker_snapshot["has_safety_blockers"]:
                        raise HTTPException(
                            status_code=409,
                            detail=server_restart_error_detail(
                                "server_restart_unsafe_busy",
                                server_restart_safety_work_message(
                                    maintenance_count,
                                    mutation_count,
                                    deleting_count,
                                    codex_goals_reconfiguring,
                                ),
                                action=(
                                    "Wait for safety-critical server work to finish, "
                                    "then refresh restart status."
                                ),
                                retryable=True,
                                server_maintenance_count=maintenance_count,
                                mutation_count=mutation_count,
                                deleting_session_count=deleting_count,
                                codex_goals_reconfiguring=(
                                    codex_goals_reconfiguring
                                ),
                                blocker_snapshot=blocker_snapshot,
                            ),
                        )
                    if blocker_snapshot["has_forceable_blockers"] and not forced:
                        raise HTTPException(
                            status_code=409,
                            detail=server_restart_error_detail(
                                "server_restart_busy",
                                server_restart_work_message(
                                    active_count,
                                    queued_count,
                                    provider_count,
                                    0,
                                    tmux_server_in_service_cgroup=bool(
                                        blocker_snapshot[
                                            "tmux_server_in_service_cgroup"
                                        ]
                                    ),
                                    tmux_server_cgroup_unknown=bool(
                                        blocker_snapshot[
                                            "tmux_server_cgroup_unknown"
                                        ]
                                    ),
                                ),
                                action="Wait for current work to finish, then retry.",
                                retryable=True,
                                active_count=active_count,
                                restart_blocking_queued_count=queued_count,
                                provider_background_count=provider_count,
                                tmux_server_in_service_cgroup=bool(
                                    blocker_snapshot[
                                        "tmux_server_in_service_cgroup"
                                    ]
                                ),
                                tmux_server_cgroup_unknown=bool(
                                    blocker_snapshot[
                                        "tmux_server_cgroup_unknown"
                                    ]
                                ),
                                blocker_snapshot=blocker_snapshot,
                            ),
                        )
                    try:
                        restart_hub_snapshot = await TEAM_HUB_RUNTIME.prepare_maintenance(
                            "server-restart",
                            persistent_fence=False,
                            allow_unavailable_host=True,
                        )
                    except Exception as exc:
                        raise HTTPException(
                            status_code=503,
                            detail=server_restart_error_detail(
                                "team_hub_snapshot_failed",
                                "AgentsServer could not verify the Team Hub restart snapshot.",
                                action=(
                                    "Retry after checking the designated host's local Team Hub logs."
                                ),
                                retryable=True,
                            ),
                        ) from exc
                    now = update_utc_now()
                    forced_work_snapshot = public_server_restart_work_counts(
                        blocker_snapshot
                    )
                    try:
                        restart_status = write_server_restart_status(
                            phase="accepted",
                            request_id=request_id,
                            _source_instance_id=SERVER_INSTANCE_ID,
                            _request_fingerprint=request_fingerprint,
                            _forced=forced,
                            _forced_work_snapshot=(
                                forced_work_snapshot if forced else None
                            ),
                            message=(
                                "AgentsServer accepted the forced restart; any active "
                                "work will be interrupted while its user service "
                                "relaunches."
                                if forced
                                else "AgentsServer accepted the restart and will briefly "
                                "disconnect while its user service relaunches."
                            ),
                            requested_at=now,
                            completed_at=None,
                            failed_at=None,
                        )
                    except BaseException:
                        await TEAM_HUB_RUNTIME.reopen_admission()
                        raise
                    # The durable restart phase now fences every unsafe Hub
                    # mutation in the parent middleware. Reopen read admission
                    # so health/discovery remains observable until SIGTERM.
                    await TEAM_HUB_RUNTIME.reopen_admission()

        background_tasks.add_task(signal_managed_server_restart, request_id)
        return public_server_restart_status(restart_status)


async def server_update_status(
    expected_server_identity: str | None = None,
    expected_server_instance_id: str | None = None,
) -> dict[str, Any]:
    async with SERVER_UPDATE_OPERATION_LOCK:
        require_server_update_target(
            expected_server_identity,
            expected_server_instance_id,
        )
        status = read_server_update_status()
        phase = str(status.get("phase") or "")
        if phase in SERVER_UPDATE_ACTIVE_PHASES:
            updater_active = await asyncio.to_thread(server_update_is_active, status)
            updater_stale = (
                not updater_active
                and server_update_status_age_seconds(status)
                >= SERVER_UPDATE_START_GRACE_SECONDS
            )
            if updater_stale:
                try:
                    status = await asyncio.to_thread(
                        finalize_abandoned_server_update,
                        status,
                    )
                except Exception as exc:
                    logger.error(
                        "server update finalization failed error_type=%s",
                        type(exc).__name__,
                    )
        # A detached runner can publish a terminal failure while this original
        # server process remains alive. Reconcile that durable phase with the
        # process-local terminal gate so clients need neither a restart nor a
        # second update attempt before reconnecting.
        public_status = public_server_update_status(status)
        await TERMINAL_ATTACHMENTS.reopen_if_update_inactive(public_status)
        if managed_server_update_is_pending(status):
            await JOBS.resume_update_parked(
                active_schedule_id=str(status.get("schedule_id") or "").strip(),
            )
        elif not managed_server_update_blocks_work(status):
            await JOBS.resume_update_parked()
        return public_status


async def check_server_update(
    body: ServerUpdateCheckRequest | None = None,
) -> dict[str, Any]:
    async with SERVER_UPDATE_OPERATION_LOCK:
        require_server_update_target(
            body.expected_server_identity if body is not None else None,
            body.expected_server_instance_id if body is not None else None,
        )
        if managed_server_restart_blocks_work():
            raise HTTPException(
                status_code=409,
                detail="AgentsServer is restarting",
            )
        status = read_server_update_status()
        if managed_server_update_is_pending(status):
            return public_server_update_status(status)
        if str(status.get("phase") or "") in SERVER_UPDATE_ACTIVE_PHASES:
            updater_active = await asyncio.to_thread(server_update_is_active, status)
            if (
                updater_active
                or server_update_status_age_seconds(status)
                < SERVER_UPDATE_START_GRACE_SECONDS
            ):
                raise HTTPException(
                    status_code=409,
                    detail="a server update is already running",
                )
            try:
                status = await asyncio.to_thread(
                    finalize_abandoned_server_update,
                    status,
                )
            except Exception as exc:
                raise HTTPException(
                    status_code=503,
                    detail="the previous server update could not be safely finalized",
                ) from exc
        track: Literal["stable", "beta"] = (
            body.track
            if body is not None and body.track is not None
            else status["track"]
        )
        try:
            manifest = await signed_release_manifest(track)
        except HTTPException as exc:
            if exc.status_code != 404:
                raise
            return public_server_update_status(
                write_fresh_server_update_status(
                    phase="unavailable",
                    track=track,
                    update_available=False,
                    message=str(exc.detail),
                    checked_at=update_utc_now(),
                )
            )
        latest = str(manifest["version"])
        current_track = server_release_track(SERVER_VERSION)
        channel_switch = track != current_track
        update_available = server_release_transition_allowed(
            latest,
            SERVER_VERSION,
            track,
        )
        if update_available and channel_switch:
            message = (
                f"Switch to {track} AgentsServer {latest}."
            )
        elif update_available:
            message = f"AgentsServer {latest} is available."
        else:
            message = f"AgentsServer {SERVER_VERSION} is current on {track}."
        return public_server_update_status(
            write_fresh_server_update_status(
                phase="available" if update_available else "current",
                track=track,
                current_track=current_track,
                latest_version=latest,
                update_available=update_available,
                channel_switch=channel_switch,
                message=message,
                checked_at=update_utc_now(),
            )
        )


async def _start_server_update(
    body: ServerUpdateRequest,
    *,
    expected_schedule_id: str | None = None,
) -> dict[str, Any]:
    async with SERVER_UPDATE_OPERATION_LOCK:
        require_server_update_target(
            body.expected_server_identity,
            body.expected_server_instance_id,
        )
        if managed_server_restart_blocks_work():
            raise HTTPException(
                status_code=409,
                detail="AgentsServer is restarting",
            )
        status = read_server_update_status()
        if str(status.get("phase") or "") in SERVER_UPDATE_ACTIVE_PHASES:
            updater_active = await asyncio.to_thread(server_update_is_active, status)
            if (
                updater_active
                or server_update_status_age_seconds(status)
                < SERVER_UPDATE_START_GRACE_SECONDS
            ):
                raise HTTPException(
                    status_code=409,
                    detail="a server update is already running",
                )
            try:
                status = await asyncio.to_thread(
                    finalize_abandoned_server_update,
                    status,
                )
            except Exception as exc:
                raise HTTPException(
                    status_code=503,
                    detail="the previous server update could not be safely finalized",
                ) from exc
        pending_schedule_id = (
            str(status.get("schedule_id") or "").strip()
            if managed_server_update_is_pending(status)
            else ""
        )
        if (
            expected_schedule_id is not None
            and pending_schedule_id != expected_schedule_id
        ):
            # A stale waiter lost its durable compare-and-swap ownership.
            return status
        track: Literal["stable", "beta"] = body.track or status["track"]
        requested = str(body.version or status.get("latest_version") or "").strip()
        if not requested:
            raise HTTPException(status_code=409, detail="check for a signed server update before installing")
        try:
            version_key(requested)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail="the requested server version is invalid") from exc
        if server_release_track(requested) != track:
            raise HTTPException(
                status_code=400,
                detail=f"the requested server version is not on the {track} track",
            )
        if pending_schedule_id:
            pending_matches = (
                requested == str(status.get("target_version") or "").strip()
                and track == status.get("track")
            )
            if not pending_matches or (
                expected_schedule_id is None and not body.when_idle
            ):
                raise HTTPException(
                    status_code=409,
                    detail=server_update_error_detail(
                        "server_update_pending",
                        "A different update is already scheduled for when the server is idle.",
                        action="Cancel the scheduled update before choosing another release.",
                        retryable=True,
                        schedule_id=pending_schedule_id,
                        target_version=status.get("target_version"),
                        track=status.get("track"),
                    ),
                )
        if not server_release_transition_allowed(requested, SERVER_VERSION, track):
            return write_fresh_server_update_status(
                phase="current",
                track=track,
                latest_version=requested,
                update_available=False,
                message=(
                    f"AgentsServer {SERVER_VERSION} is current; managed updates "
                    "only move forward or switch from beta to the latest stable release."
                ),
                checked_at=update_utc_now(),
            )
        if (
            track == "stable"
            and server_release_track(SERVER_VERSION) == "beta"
        ):
            # Beta-to-stable is the only transition allowed to move backward
            # in SemVer precedence. Resolve the signed channel again at the
            # exact admission point so a caller or a recovered idle schedule
            # cannot use that exception to select an arbitrary old release.
            latest_manifest = await signed_release_manifest("stable")
            latest_stable = str(latest_manifest.get("version") or "").strip()
            if latest_stable != requested:
                raise HTTPException(
                    status_code=409,
                    detail=server_update_error_detail(
                        "server_update_target_superseded",
                        (
                            f"Stable AgentsServer {latest_stable} is now the latest "
                            f"signed release; {requested} will not be installed."
                        ),
                        action=(
                            "Refresh the server update status and retry the latest "
                            "stable release."
                        ),
                        retryable=True,
                        latest_version=latest_stable,
                    ),
                )
        tmux = tmux_capability()
        if not tmux["available"]:
            raise HTTPException(status_code=503, detail=f"{tmux['message']} {tmux['action']}")
        if not SERVER_UPDATE_RUNNER.is_file() or not SERVER_UPDATE_PUBLIC_KEY.is_file():
            raise HTTPException(status_code=503, detail="this server installation predates managed updates; run the installer once")
        # Check before closing admission or writing a durable drain phase. A
        # detached updater in this service cgroup cannot survive install.sh's
        # systemctl --user restart.
        service_cgroup = await asyncio.to_thread(
            ensure_managed_update_tmux_isolated
        )
        provider_work_snapshot = (
            await prepare_provider_background_work_snapshot()
        )

        update_id = ""
        tmux_name = ""
        command: list[str] = []
        auth_token_file: Path | None = None
        channel_switch = track != server_release_track(SERVER_VERSION)
        hub_snapshot: Path | None = None
        # Close admission and establish the durable update phase while holding
        # the same lock used to reserve turns.  This removes the race where a
        # turn could start after an idle check but before the detached updater
        # was launched.
        async with ACTIVE_LOCK:
            async with QUEUE_LOCK:
                async with UNSAFE_HTTP_MUTATION_ADMISSION_LOCK:
                    active_session_ids = (
                        server_update_active_session_ids_locked()
                    )
                    queued_turn_count = update_blocking_queued_turn_count_locked()
                    mutation_count = unsafe_http_mutation_count_locked()
                    duplicate_provider_labels = {
                        *(f"active chat {session_id}" for session_id in BUSY_SESSIONS),
                        *(
                            f"Codex maintenance for {session_id}"
                            for session_id in SERVER_MAINTENANCE_SESSIONS
                        ),
                    }
                    provider_work_labels = [
                        label
                        for label in provider_background_work_labels_from_snapshot(
                            provider_work_snapshot
                        )
                        if label not in duplicate_provider_labels
                    ]
                    blocker_counts = server_update_blocker_counts(
                        active_session_ids,
                        queued_turn_count,
                        provider_work_labels,
                        mutation_count,
                    )
                    if server_update_has_blockers(blocker_counts):
                        if body.when_idle:
                            schedule_id = (
                                expected_schedule_id
                                or pending_schedule_id
                                or uuid.uuid4().hex
                            )
                            if (
                                schedule_id == pending_schedule_id
                                and status.get("blocker_counts")
                                == blocker_counts
                            ):
                                return status
                            pending_at = (
                                status.get("pending_at")
                                if schedule_id == pending_schedule_id
                                else update_utc_now()
                            )
                            pending_status = write_fresh_server_update_status(
                                schedule_id=schedule_id,
                                phase=SERVER_UPDATE_PENDING_PHASE,
                                track=track,
                                current_track=server_release_track(SERVER_VERSION),
                                channel_switch=channel_switch,
                                target_version=requested,
                                latest_version=requested,
                                update_available=True,
                                when_idle=True,
                                cancelable=True,
                                pending_at=pending_at,
                                blocker_counts=blocker_counts,
                                message=server_update_pending_message(
                                    requested,
                                    blocker_counts,
                                ),
                                checked_at=status.get("checked_at"),
                            )
                            return pending_status
                        raise HTTPException(
                            status_code=409,
                            detail=server_update_work_message(
                                active_session_ids,
                                queued_turn_count,
                                provider_work_labels,
                                mutation_count,
                            ),
                        )
                    update_id = uuid.uuid4().hex
                    tmux_name = server_update_tmux_name(update_id)
                    command = [
                        sys.executable,
                        str(SERVER_UPDATE_RUNNER),
                        "--status-file", str(SERVER_UPDATE_STATUS_FILE),
                        "--public-key", str(SERVER_UPDATE_PUBLIC_KEY),
                        "--port", str(SERVER_PORT),
                        "--bind", SERVER_BIND_ADDRESS,
                        "--expected-version", requested,
                        "--current-version", SERVER_VERSION,
                        "--track", track,
                        "--update-id", update_id,
                    ]
                    if service_cgroup is not None:
                        command.extend(
                            ["--expected-service-cgroup", service_cgroup]
                        )
                    if AGENT_TOKEN:
                        auth_token_file = SERVER_UPDATE_STATUS_FILE.with_name(
                            f".server-update-{update_id}.auth.json"
                        )
                        command.extend(
                            ["--auth-token-file", str(auth_token_file)]
                        )
                    expected_server_identity = server_identity()
                    hub_capability = TEAM_HUB_RUNTIME.capability()
                    try:
                        hub_snapshot = await TEAM_HUB_RUNTIME.prepare_maintenance(
                            "server-update",
                            operation_id=update_id,
                            allow_unavailable_host=True,
                        )
                    except Exception as exc:
                        raise HTTPException(
                            status_code=503,
                            detail=(
                                "AgentsServer could not verify the Team Hub update "
                                "snapshot; retry after checking local Team Hub logs"
                            ),
                        ) from exc
                    command.extend(
                        ["--expected-server-identity", expected_server_identity]
                    )
                    expected_hub_id: str | None = None
                    expected_hub_transport: str | None = None
                    expected_hub_url: str | None = None
                    expected_hub_routes: list[dict[str, Any]] | None = None
                    expected_hub_direct_ip_url: str | None = None
                    failed_hub_repair = bool(
                        hub_snapshot is None
                        and hub_capability.get("designated_host") is True
                        and hub_capability.get("available") is False
                        and isinstance(
                            hub_capability.get("startup_failure_reason"), str
                        )
                        and str(
                            hub_capability.get("startup_failure_reason") or ""
                        ).strip()
                    )
                    if hub_snapshot is not None:
                        expected_hub_id = str(hub_capability.get("hub_id") or "")
                        expected_hub_transport = str(
                            hub_capability.get("transport") or ""
                        )
                        raw_hub_url = hub_capability.get("hub_url")
                        expected_hub_url = (
                            str(raw_hub_url) if raw_hub_url is not None else None
                        )
                        raw_hub_routes = hub_capability.get("routes")
                        expected_hub_routes = (
                            [dict(route) for route in raw_hub_routes]
                            if isinstance(raw_hub_routes, list)
                            and all(isinstance(route, dict) for route in raw_hub_routes)
                            else None
                        )
                        if expected_hub_routes is not None:
                            expected_hub_direct_ip_url = next(
                                (
                                    str(route.get("hub_url") or "")
                                    for route in expected_hub_routes
                                    if route.get("transport") == "direct_ip"
                                ),
                                "",
                            )
                        if (
                            hub_capability.get("available") is not True
                            or hub_capability.get("designated_host") is not True
                            or not expected_hub_id
                            or expected_hub_transport
                            not in {"loopback", "tailscale_serve", "direct_ip"}
                            or (
                                expected_hub_transport == "loopback"
                                and expected_hub_url is not None
                            )
                            or (
                                expected_hub_transport == "tailscale_serve"
                                and not expected_hub_url
                            )
                            or (
                                expected_hub_transport == "direct_ip"
                                and not expected_hub_url
                            )
                            or not expected_hub_routes
                        ):
                            try:
                                await TEAM_HUB_RUNTIME.clear_maintenance(
                                    "server-update",
                                    update_id,
                                    hub_snapshot,
                                )
                            finally:
                                await TEAM_HUB_RUNTIME.reopen_admission()
                            raise HTTPException(
                                status_code=503,
                                detail="designated Team Hub identity is unavailable",
                            )
                        command.extend(
                            [
                                "--expected-team-hub-id",
                                expected_hub_id,
                                "--expected-team-hub-transport",
                                expected_hub_transport,
                                "--expected-team-hub-url",
                                expected_hub_url or "",
                                "--expected-team-hub-direct-ip-url",
                                expected_hub_direct_ip_url or "",
                                "--team-hub-snapshot",
                                str(hub_snapshot),
                                "--team-hub-data-dir",
                                str(TEAM_HUB_DATA_DIR),
                            ]
                        )
                    elif failed_hub_repair:
                        expected_hub_transport = str(
                            hub_capability.get("transport") or ""
                        )
                        raw_hub_url = hub_capability.get("hub_url")
                        expected_hub_url = (
                            str(raw_hub_url) if raw_hub_url is not None else None
                        )
                        raw_hub_routes = hub_capability.get("routes")
                        expected_hub_routes = (
                            [dict(route) for route in raw_hub_routes]
                            if isinstance(raw_hub_routes, list)
                            and all(isinstance(route, dict) for route in raw_hub_routes)
                            else None
                        )
                        if expected_hub_routes is not None:
                            expected_hub_direct_ip_url = next(
                                (
                                    str(route.get("hub_url") or "")
                                    for route in expected_hub_routes
                                    if route.get("transport") == "direct_ip"
                                ),
                                "",
                            )
                        if (
                            expected_hub_transport
                            not in {"loopback", "tailscale_serve", "direct_ip"}
                            or (
                                expected_hub_transport == "loopback"
                                and expected_hub_url is not None
                            )
                            or (
                                expected_hub_transport in {
                                    "tailscale_serve",
                                    "direct_ip",
                                }
                                and not expected_hub_url
                            )
                            or not expected_hub_routes
                        ):
                            raise HTTPException(
                                status_code=503,
                                detail=(
                                    "failed Team Hub host configuration is unavailable "
                                    "for a verified repair update"
                                ),
                            )
                        command.extend(
                            [
                                "--repair-failed-team-hub-host",
                                "--expected-team-hub-transport",
                                expected_hub_transport,
                                "--expected-team-hub-url",
                                expected_hub_url or "",
                                "--expected-team-hub-direct-ip-url",
                                expected_hub_direct_ip_url or "",
                            ]
                        )
                    try:
                        status = write_fresh_server_update_status(
                            schedule_id=(pending_schedule_id or None),
                            update_id=update_id,
                            phase="starting",
                            track=track,
                            current_track=server_release_track(SERVER_VERSION),
                            channel_switch=channel_switch,
                            target_version=requested,
                            latest_version=requested,
                            update_available=True,
                            when_idle=bool(pending_schedule_id),
                            cancelable=False,
                            pending_at=(
                                status.get("pending_at")
                                if pending_schedule_id
                                else None
                            ),
                            blocker_counts=server_update_blocker_counts(
                                [],
                                0,
                                [],
                                0,
                            ),
                            team_hub_id=expected_hub_id,
                            team_hub_host_server_identity=(
                                expected_server_identity
                                if hub_snapshot is not None or failed_hub_repair
                                else None
                            ),
                            team_hub_snapshot_generation=(
                                hub_snapshot.name if hub_snapshot is not None else None
                            ),
                            team_hub_transport=expected_hub_transport,
                            team_hub_url=expected_hub_url,
                            team_hub_direct_ip_url=expected_hub_direct_ip_url,
                            team_hub_routes=expected_hub_routes,
                            team_hub_repair_mode=(
                                "failed_start" if failed_hub_repair else None
                            ),
                            message=(
                                f"Starting switch to {track} AgentsServer {requested}."
                                if channel_switch
                                else (
                                    f"Starting detached update to AgentsServer "
                                    f"{requested}."
                                )
                            ),
                            started_at=update_utc_now(),
                            finished_at=None,
                        )
                    except BaseException:
                        try:
                            if hub_snapshot is not None:
                                await TEAM_HUB_RUNTIME.clear_maintenance(
                                    "server-update",
                                    update_id,
                                    hub_snapshot,
                                )
                        finally:
                            await TEAM_HUB_RUNTIME.reopen_admission()
                        raise
                    # The durable starting phase now closes unsafe mutation
                    # admission. Reads may resume while the detached updater
                    # downloads and verifies the release.
                    TEAM_HUB_RUNTIME.reopen_admission_sync()

        async def fail_runner_launch(exc: BaseException) -> None:
            if auth_token_file is not None:
                with suppress(FileNotFoundError):
                    auth_token_file.unlink()
            public_error = public_server_update_launch_error(exc)
            logger.warning(
                "detached server updater prelaunch failed error_type=%s error_code=%s",
                type(exc).__name__,
                public_error.get("error_code") or "unclassified",
            )
            fence_clear_failed = False
            try:
                if hub_snapshot is not None:
                    await TEAM_HUB_RUNTIME.clear_maintenance(
                        "server-update",
                        update_id,
                        hub_snapshot,
                    )
            except Exception:
                fence_clear_failed = True
                logger.error("Team Hub update fence clear failed after runner launch failure")
            try:
                if not fence_clear_failed:
                    if public_error.get("retryable") is True:
                        write_fresh_server_update_status(
                            phase="available",
                            track=track,
                            current_track=server_release_track(SERVER_VERSION),
                            channel_switch=channel_switch,
                            latest_version=requested,
                            update_available=True,
                            checked_at=status.get("checked_at"),
                            **public_error,
                        )
                    else:
                        write_server_update_status(
                            phase="failed",
                            message=public_error["message"],
                            error_code=public_error["error_code"],
                            error_action=public_error["error_action"],
                            retryable=False,
                            finished_at=update_utc_now(),
                        )
            finally:
                await TEAM_HUB_RUNTIME.reopen_admission()
            if not fence_clear_failed:
                await TERMINAL_ATTACHMENTS.reopen_admission()
                # A failed detached launch reopened normal work admission.
                # Resume durable queues now instead of leaving them parked
                # until an unrelated retry timer or server restart.
                schedule_rebuilt_queued_turns()

        async def settle_failed_runner_launch(
            exc: BaseException,
        ) -> asyncio.CancelledError | None:
            """Finish every failure side effect despite caller cancellation."""

            cleanup_task = asyncio.create_task(fail_runner_launch(exc))
            try:
                await asyncio.shield(cleanup_task)
                return None
            except asyncio.CancelledError as cancellation:
                await join_task_despite_caller_cancellation(cleanup_task)
                return cancellation

        # The durable drain is now authoritative. Retire only the known idle
        # provider supervisors, then fail closed if any other process remains
        # in the exact service cgroup. Shield teardown so cancellation cannot
        # reopen admission while a stale supervisor is still being retired.
        quiesce_task = asyncio.create_task(
            quiesce_managed_update_service_cgroup(
                service_cgroup=service_cgroup,
            )
        )
        try:
            await asyncio.shield(quiesce_task)
        except asyncio.CancelledError as cancellation:
            quiesce_error: BaseException | None = None
            try:
                await join_task_despite_caller_cancellation(quiesce_task)
            except BaseException as exc:
                quiesce_error = exc
            await settle_failed_runner_launch(
                quiesce_error
                or RuntimeError("update request ended before detached launch")
            )
            raise cancellation
        except HTTPException as exc:
            cleanup_cancellation = await settle_failed_runner_launch(exc)
            if cleanup_cancellation is not None:
                raise cleanup_cancellation
            raise
        except Exception as exc:
            cleanup_cancellation = await settle_failed_runner_launch(exc)
            if cleanup_cancellation is not None:
                raise cleanup_cancellation
            raise HTTPException(
                status_code=500,
                detail="could not safely quiesce AgentsServer for update",
            ) from exc

        try:
            runner_environment = server_update_runner_environment()
            if runner_environment:
                command = [
                    "env",
                    *(f"{key}={value}" for key, value in runner_environment.items()),
                    *command,
                ]
            if auth_token_file is not None:
                atomic_update_json(auth_token_file, {"token": AGENT_TOKEN})
            runner_shell_command = (
                f"{shlex.quote(tmux_bin())} set-option -w remain-on-exit off "
                f">/dev/null 2>&1 && exec {shlex.join(command)}"
            )
            launch_task = asyncio.create_task(
                asyncio.to_thread(
                    run_tmux,
                    ["new-session", "-d", "-s", tmux_name, runner_shell_command],
                )
            )
            try:
                await asyncio.shield(launch_task)
            except asyncio.CancelledError as cancellation:
                launch_error: BaseException | None = None
                try:
                    await join_task_despite_caller_cancellation(launch_task)
                except BaseException as exc:
                    launch_error = exc
                if launch_error is not None:
                    await settle_failed_runner_launch(launch_error)
                raise cancellation
        except Exception as exc:
            cleanup_cancellation = await settle_failed_runner_launch(exc)
            if cleanup_cancellation is not None:
                raise cleanup_cancellation
            raise HTTPException(status_code=500, detail="could not start detached updater") from exc
        return status


async def start_server_update(body: ServerUpdateRequest) -> dict[str, Any]:
    return public_server_update_status(await _start_server_update(body))


async def cancel_server_update(
    body: ServerUpdateCancelRequest,
) -> dict[str, Any]:
    """Cancel exactly one durable idle reservation before launch begins."""

    async with SERVER_UPDATE_OPERATION_LOCK:
        require_server_update_target(
            body.expected_server_identity,
            body.expected_server_instance_id,
        )
        status = read_server_update_status()
        actual_schedule_id = str(status.get("schedule_id") or "").strip()
        if actual_schedule_id != body.schedule_id:
            raise HTTPException(
                status_code=409,
                detail=server_update_error_detail(
                    "server_update_changed",
                    "The scheduled server update changed before cancellation.",
                    action="Refresh update status before trying again.",
                    retryable=True,
                    phase=status.get("phase"),
                    schedule_id=(actual_schedule_id or None),
                ),
            )
        if not managed_server_update_is_pending(status):
            raise HTTPException(
                status_code=409,
                detail=server_update_error_detail(
                    "server_update_not_cancelable",
                    "The server update has already started and cannot be canceled.",
                    action="Wait for the managed update to finish.",
                    retryable=False,
                    phase=status.get("phase"),
                    schedule_id=actual_schedule_id,
                    update_id=status.get("update_id"),
                ),
            )
        target = str(status.get("target_version") or "").strip()
        track: Literal["stable", "beta"] = (
            "beta" if status.get("track") == "beta" else "stable"
        )
        cancelled = write_fresh_server_update_status(
            phase="available",
            track=track,
            current_track=server_release_track(SERVER_VERSION),
            latest_version=(target or None),
            update_available=bool(target),
            channel_switch=(track != server_release_track(SERVER_VERSION)),
            message=(
                f"Scheduled update to AgentsServer {target} was canceled."
                if target
                else "The scheduled server update was canceled."
            ),
            checked_at=status.get("checked_at"),
        )
        public_status = public_server_update_status(cancelled)
        await TERMINAL_ATTACHMENTS.reopen_if_update_inactive(public_status)
        # The status transition and exact job rearm share the operation lock,
        # so a concurrent scheduler park cannot land after cancellation.
        await JOBS.resume_update_parked(actual_schedule_id)
        # Messages accepted while the drain was pending are already durable.
        # Wake their queues immediately when the user cancels instead of
        # waiting for the periodic deferred-turn retry.
        schedule_rebuilt_queued_turns()
        return public_status


