@app.put("/api/sessions/{session_id}/codex/goal")
async def put_codex_goal(
    session_id: str,
    req: CodexGoalRequest,
) -> dict[str, Any]:
    async with session_lifecycle_lock(session_id):
        ensure_session_not_deleting(session_id)
        return await _put_codex_goal_locked(session_id, req)


async def _put_codex_goal_locked(
    session_id: str,
    req: CodexGoalRequest,
) -> dict[str, Any]:
    if not CODEX_GOALS_ENABLED:
        raise HTTPException(
            status_code=409,
            detail=(
                "Persistent Codex goals are disabled for this server. "
                "Enable them in server settings before creating or updating a goal."
            ),
        )
    fields_set = request_fields_set(req)
    if not fields_set:
        raise HTTPException(status_code=400, detail="provide at least one goal field")
    manager, thread_id, _session = await acquire_codex_control_thread(
        session_id,
        allow_active_goal_mutation=True,
    )
    try:
        native_fields = fields_set & {"objective", "status", "token_budget"}
        stored_session = STORE.sessions.get(session_id, {})
        previous_goal = stored_session.get("codex_goal")
        goal = previous_goal
        previous_time_budget = stored_session.get(
            "codex_goal_time_budget_seconds"
        )
        time_budget_exhausted = bool(
            stored_session.get("codex_goal_time_budget_exhausted")
        )
        if native_fields:
            kwargs: dict[str, Any] = {}
            if "objective" in fields_set:
                kwargs["objective"] = (
                    str(req.objective).strip() if req.objective is not None else None
                )
            if "status" in fields_set:
                kwargs["status"] = req.status
            if "token_budget" in fields_set:
                kwargs["token_budget"] = req.token_budget
            goal = await asyncio.wait_for(
                manager.set_thread_goal(thread_id, **kwargs),
                timeout=CODEX_GOAL_CONTROL_TIMEOUT_SECONDS,
            )
        if not isinstance(goal, dict):
            raise HTTPException(
                status_code=409,
                detail="set an objective before configuring a time limit",
            )
        time_budget_seconds = (
            req.time_budget_seconds
            if "time_budget_seconds" in fields_set
            else previous_time_budget
        )
        previous_objective = (
            str(previous_goal.get("objective") or "")
            if isinstance(previous_goal, dict)
            else ""
        )
        current_objective = str(goal.get("objective") or "")
        if "objective" in fields_set and current_objective != previous_objective:
            time_budget_exhausted = False
        if "time_budget_seconds" in fields_set:
            if time_budget_seconds is None:
                time_budget_exhausted = False
            elif (
                not isinstance(previous_time_budget, (int, float))
                or isinstance(previous_time_budget, bool)
                or float(time_budget_seconds) > float(previous_time_budget)
            ):
                time_budget_exhausted = False
        used = goal.get("timeUsedSeconds")
        if (
            time_budget_seconds is not None
            and isinstance(used, (int, float))
            and not isinstance(used, bool)
            and float(used) >= float(time_budget_seconds)
        ):
            time_budget_exhausted = True
        async with STORE._lock:
            current = STORE.sessions.get(session_id)
            if current:
                current["codex_goal"] = goal
                current["codex_goal_time_budget_seconds"] = time_budget_seconds
                current["codex_goal_time_budget_exhausted"] = (
                    time_budget_exhausted
                )
                current["updated_at"] = now_iso()
                await STORE.save()
        if fields_set == {"time_budget_seconds"}:
            await append_event(
                session_id,
                "codex_goal_updated",
                {
                    "goal": goal,
                    "time_budget_seconds": time_budget_seconds,
                    "time_budget_owner": "AgentsDock",
                },
            )
        return {
            "goal": goal,
            "time_budget_seconds": time_budget_seconds,
            "time_budget_exhausted": time_budget_exhausted,
        }
    except asyncio.TimeoutError as exc:
        raise HTTPException(
            status_code=504,
            detail="Codex goal update timed out. Retry the change.",
        ) from exc
    except Exception as exc:
        if isinstance(exc, HTTPException):
            raise
        raise codex_control_http_error(exc) from exc
    finally:
        await release_codex_control_thread(session_id, manager, thread_id)


@app.delete("/api/sessions/{session_id}/codex/goal")
async def delete_codex_goal(session_id: str) -> dict[str, Any]:
    async with session_lifecycle_lock(session_id):
        ensure_session_not_deleting(session_id)
        return await _delete_codex_goal_locked(session_id)


async def _delete_codex_goal_locked(session_id: str) -> dict[str, Any]:
    if not CODEX_GOALS_ENABLED:
        raise HTTPException(
            status_code=409,
            detail=(
                "Persistent Codex goals are disabled for this server. "
                "Enable them in server settings before clearing a saved goal."
            ),
        )
    def cleared_result() -> dict[str, Any]:
        return {
            "goal": None,
            "time_budget_seconds": None,
            "time_budget_exhausted": False,
        }

    try:
        manager, thread_id, _session = await acquire_codex_control_thread(
            session_id,
            allow_active_goal_mutation=True,
        )
    except HTTPException as exc:
        session = STORE.sessions.get(session_id) or {}
        stale_thread_id = str(session_provider_id(session) or "").strip()
        if stale_thread_id and is_codex_resume_failure(str(exc.detail or "")):
            await quarantine_codex_goal_thread(
                session_id,
                stale_thread_id,
                reason=(
                    "Clearing the goal found a stale provider thread: "
                    f"{concise_error_message(exc.detail)}"
                ),
                clear_goal=True,
            )
            return cleared_result()
        raise
    try:
        # Generation reconciliation may already have established that the
        # provider has no goal. In that case the user's requested terminal
        # state is satisfied and another native call is unnecessary.
        if (STORE.sessions.get(session_id) or {}).get("codex_goal") is None:
            return cleared_result()
        await asyncio.wait_for(
            manager.clear_thread_goal(thread_id),
            timeout=CODEX_GOAL_CONTROL_TIMEOUT_SECONDS,
        )
        async with STORE._lock:
            current = STORE.sessions.get(session_id)
            if current:
                current["codex_goal"] = None
                current["codex_goal_time_budget_seconds"] = None
                current["codex_goal_time_budget_exhausted"] = False
                current["updated_at"] = now_iso()
                await STORE.save()
        return cleared_result()
    except asyncio.TimeoutError:
        # The request may have reached Codex even though its response was lost.
        # Explicit Clear is nevertheless an unambiguous user intent: detach the
        # uncertain provider thread and clear local state so the goal cannot
        # keep the chat stuck behind a retry-only UI.
        await quarantine_codex_goal_thread(
            session_id,
            thread_id,
            reason=(
                "Clearing the Codex goal timed out; the provider result is "
                "ambiguous, so the old thread was detached."
            ),
            clear_goal=True,
        )
        return cleared_result()
    except Exception as exc:
        if is_codex_resume_failure(concise_error_message(exc)):
            await quarantine_codex_goal_thread(
                session_id,
                thread_id,
                reason=(
                    "Clearing the goal found a stale provider thread: "
                    f"{concise_error_message(exc)}"
                ),
                clear_goal=True,
            )
            return cleared_result()
        if isinstance(exc, HTTPException):
            raise
        raise codex_control_http_error(exc) from exc
    finally:
        await release_codex_control_thread(session_id, manager, thread_id)


@app.post("/api/sessions/{session_id}/codex/compact")
async def post_codex_compact(session_id: str) -> dict[str, Any]:
    async with session_lifecycle_lock(session_id):
        ensure_session_not_deleting(session_id)
        return await _post_codex_compact_locked(session_id)


async def _post_codex_compact_locked(session_id: str) -> dict[str, Any]:
    manager, thread_id, control_session = await acquire_codex_control_thread(
        session_id,
        reserve_session=True,
    )
    reservation_id = str(
        control_session.get("_codex_control_reservation_id") or ""
    )
    operation_id = f"codexop_{uuid.uuid4().hex[:16]}"
    subscription = manager.subscribe_thread(thread_id)
    token_usage_before = current_codex_token_usage_snapshot(session_id)
    try:
        async with ACTIVE_LOCK:
            active = ACTIVE.get(session_id)
            if active:
                active["run_id"] = operation_id
                active["codex_native_operation_kind"] = "compaction"
                active["provider_turn_id"] = None
                active["provider_turn_ready"] = False
                active["codex_compaction_in_progress"] = True
                active["codex_compaction_token_usage_before"] = (
                    dict(token_usage_before)
                    if token_usage_before is not None
                    else None
                )
                active["codex_compaction_token_usage_after"] = None
        await manager.compact_thread(thread_id)
        task = asyncio.create_task(
            consume_codex_native_turn(
                session_id,
                operation_id,
                "compaction",
                manager,
                thread_id,
                reservation_id,
                subscription,
            )
        )
        register_codex_native_action(session_id, operation_id, task)
        try:
            await append_event(
                session_id,
                "codex_compaction_started",
                {
                    "run_id": operation_id,
                    "operation_id": operation_id,
                    "thread_id": thread_id,
                    "token_usage_before": token_usage_before,
                    "message": (
                        "Codex started compacting this thread's context."
                    ),
                },
            )
        except Exception as exc:
            logger.warning(
                "failed to persist Codex compaction start session=%s: %s",
                session_id,
                concise_error_message(exc),
            )
        return {"accepted": True, "operation_id": operation_id}
    except Exception as exc:
        subscription.close()
        await release_codex_control_thread(
            session_id,
            manager,
            thread_id,
            reserved_session=True,
            reservation_id=reservation_id,
        )
        raise codex_control_http_error(exc) from exc


@app.post("/api/sessions/{session_id}/codex/rollback")
async def post_codex_rollback(
    session_id: str,
    req: CodexRollbackRequest,
) -> dict[str, Any]:
    async with session_lifecycle_lock(session_id):
        ensure_session_not_deleting(session_id)
        return await _post_codex_rollback_locked(session_id, req)


async def _post_codex_rollback_locked(
    session_id: str,
    req: CodexRollbackRequest,
) -> dict[str, Any]:
    if not req.confirmed:
        raise HTTPException(
            status_code=400,
            detail=(
                "thread/rollback permanently removes provider context and "
                "requires explicit confirmed=true"
            ),
        )
    manager, thread_id, control_session = await acquire_codex_control_thread(
        session_id,
        reserve_session=True,
    )
    reservation_id = str(
        control_session.get("_codex_control_reservation_id") or ""
    )
    try:
        thread = await manager.rollback_thread(thread_id, num_turns=req.num_turns)
        await append_event(
            session_id,
            "codex_rollback",
            {
                "num_turns": req.num_turns,
                "message": (
                    f"Codex provider context rolled back {req.num_turns} turn(s). "
                    "AgentsDock history and workspace files were not changed."
                ),
            },
        )
        return {"accepted": True, "thread": thread}
    except Exception as exc:
        raise codex_control_http_error(exc) from exc
    finally:
        await release_codex_control_thread(
            session_id,
            manager,
            thread_id,
            reserved_session=True,
            reservation_id=reservation_id,
        )


@app.post("/api/sessions/{session_id}/codex/review")
async def post_codex_review(
    session_id: str,
    req: CodexReviewRequest,
) -> dict[str, Any]:
    async with session_lifecycle_lock(session_id):
        ensure_session_not_deleting(session_id)
        return await _post_codex_review_locked(session_id, req)


async def _post_codex_review_locked(
    session_id: str,
    req: CodexReviewRequest,
) -> dict[str, Any]:
    if req.delivery != "inline":
        raise HTTPException(
            status_code=501,
            detail="Detached review requires a mapped child chat; use inline review for now",
        )
    manager, thread_id, control_session = await acquire_codex_control_thread(
        session_id,
        reserve_session=True,
    )
    reservation_id = str(
        control_session.get("_codex_control_reservation_id") or ""
    )
    operation_id = f"codexop_{uuid.uuid4().hex[:16]}"
    subscription = manager.subscribe_thread(thread_id)
    try:
        result = await manager.start_review(
            thread_id,
            req.target,
            delivery=req.delivery,
        )
        turn = (
            result.get("turn")
            if isinstance(result, dict)
            and isinstance(result.get("turn"), dict)
            else {}
        )
        turn_id = str(turn.get("id") or "")
        task = asyncio.create_task(
            consume_codex_native_turn(
                session_id,
                operation_id,
                "review",
                manager,
                thread_id,
                reservation_id,
                subscription,
                turn_id=turn_id or None,
            )
        )
        register_codex_native_action(session_id, operation_id, task)
        async with ACTIVE_LOCK:
            active = ACTIVE.get(session_id)
            if active:
                active["run_id"] = operation_id
                active["codex_native_operation_kind"] = "review"
                active["provider_turn_id"] = turn_id or None
                active["provider_turn_ready"] = bool(turn_id)
        try:
            await append_event(
                session_id,
                "codex_review_started",
                {
                    "operation_id": operation_id,
                    "turn_id": turn_id or None,
                    "target": bounded_codex_interaction_value(req.target),
                    "delivery": req.delivery,
                    "message": "Codex started an inline code review.",
                },
            )
        except Exception as exc:
            logger.warning(
                "failed to persist Codex review start session=%s: %s",
                session_id,
                concise_error_message(exc),
            )
        return {
            "accepted": True,
            "operation_id": operation_id,
            "turn_id": turn_id or None,
        }
    except Exception as exc:
        subscription.close()
        await release_codex_control_thread(
            session_id,
            manager,
            thread_id,
            reserved_session=True,
            reservation_id=reservation_id,
        )
        raise codex_control_http_error(exc) from exc


@app.post("/api/sessions/{session_id}/codex/shell")
async def post_codex_shell_command(
    session_id: str,
    req: CodexShellCommandRequest,
) -> dict[str, Any]:
    async with session_lifecycle_lock(session_id):
        ensure_session_not_deleting(session_id)
        return await _post_codex_shell_command_locked(session_id, req)


async def _post_codex_shell_command_locked(
    session_id: str,
    req: CodexShellCommandRequest,
) -> dict[str, Any]:
    if not req.confirmed:
        raise HTTPException(
            status_code=400,
            detail=(
                "thread/shellCommand is unsandboxed and requires explicit "
                "confirmed=true"
            ),
        )
    manager, thread_id, control_session = await acquire_codex_control_thread(
        session_id,
        reserve_session=True,
    )
    reservation_id = str(
        control_session.get("_codex_control_reservation_id") or ""
    )
    operation_id = f"codexop_{uuid.uuid4().hex[:16]}"
    subscription = manager.subscribe_thread(thread_id)
    try:
        async with ACTIVE_LOCK:
            active = ACTIVE.get(session_id)
            if active:
                active["run_id"] = operation_id
                active["codex_native_operation_kind"] = "shell"
                active["provider_turn_id"] = None
                active["provider_turn_ready"] = False
        await manager.run_thread_shell_command(thread_id, req.command)
        task = asyncio.create_task(
            consume_codex_native_turn(
                session_id,
                operation_id,
                "shell",
                manager,
                thread_id,
                reservation_id,
                subscription,
            )
        )
        register_codex_native_action(session_id, operation_id, task)
        try:
            await append_event(
                session_id,
                "codex_shell_started",
                {
                    "operation_id": operation_id,
                    "command": req.command,
                    "unsandboxed": True,
                    "message": (
                        "Codex started the confirmed unsandboxed shell command."
                    ),
                },
            )
        except Exception as exc:
            logger.warning(
                "failed to persist Codex shell start session=%s: %s",
                session_id,
                concise_error_message(exc),
            )
        return {"accepted": True, "operation_id": operation_id}
    except Exception as exc:
        subscription.close()
        await release_codex_control_thread(
            session_id,
            manager,
            thread_id,
            reserved_session=True,
            reservation_id=reservation_id,
        )
        raise codex_control_http_error(exc) from exc


@app.get("/api/sessions/{session_id}/codex/background-terminals")
async def get_codex_background_terminals(session_id: str) -> dict[str, Any]:
    async with session_lifecycle_lock(session_id):
        ensure_session_not_deleting(session_id)
        return await _get_codex_background_terminals_locked(session_id)


async def _get_codex_background_terminals_locked(
    session_id: str,
) -> dict[str, Any]:
    global CODEX_BACKGROUND_TERMINALS_SUPPORTED
    manager, thread_id, _session = await acquire_codex_control_thread(session_id)
    try:
        terminals = await manager.list_background_terminals(thread_id)
        CODEX_BACKGROUND_TERMINALS_SUPPORTED = True
        return {"supported": True, "terminals": terminals}
    except Exception as exc:
        if isinstance(exc, CodexAppServerRequestError) and exc.code in {
            -32600,
            -32601,
        }:
            CODEX_BACKGROUND_TERMINALS_SUPPORTED = False
            return {"supported": False, "terminals": []}
        raise codex_control_http_error(exc) from exc
    finally:
        await release_codex_control_thread(session_id, manager, thread_id)


