async def bridge_port_tunnel(
    ws: WebSocket,
    reader: asyncio.StreamReader,
    writer: asyncio.StreamWriter,
) -> tuple[int, str] | None:
    """Copy unmodified bytes until either side closes the tunnel."""

    async def remote_to_websocket() -> tuple[int, str]:
        while True:
            data = await reader.read(PORT_TUNNEL_READ_CHUNK_BYTES)
            if not data:
                return (1000, "Loopback service closed the connection")
            await asyncio.wait_for(
                ws.send_bytes(data),
                timeout=PORT_TUNNEL_IO_TIMEOUT_SECONDS,
            )

    async def websocket_to_remote() -> tuple[int, str] | None:
        while True:
            message = await ws.receive()
            if message.get("type") == "websocket.disconnect":
                return None
            data = message.get("bytes")
            if data is not None:
                if len(data) > PORT_TUNNEL_MAX_CLIENT_FRAME_BYTES:
                    return (
                        PORT_TUNNEL_CLOSE_INVALID_REQUEST,
                        "Binary tunnel frame exceeds the server limit",
                    )
                writer.write(data)
                await asyncio.wait_for(
                    writer.drain(),
                    timeout=PORT_TUNNEL_IO_TIMEOUT_SECONDS,
                )
                continue
            if message.get("text") is not None:
                return (
                    PORT_TUNNEL_CLOSE_PROTOCOL_REQUIRED,
                    "Port tunnels accept binary WebSocket frames only",
                )

    tasks = {
        asyncio.create_task(remote_to_websocket()),
        asyncio.create_task(websocket_to_remote()),
    }
    try:
        done: set[asyncio.Task[tuple[int, str] | None]]
        done, _pending = await asyncio.wait(
            tasks,
            return_when=asyncio.FIRST_COMPLETED,
        )
        results = [task.result() for task in done]
        return next((result for result in results if result is not None), None)
    finally:
        # The route task is the lifecycle owner registered below. When archive,
        # deletion, or shutdown cancels it, both directional pumps must be
        # retired before the route can release its tracked reservation.
        for task in tasks:
            if not task.done():
                task.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)


@app.websocket("/api/sessions/{session_id}/ports/{port}/tunnel/ws")
async def session_port_tunnel(
    session_id: str,
    port: str,
    ws: WebSocket,
) -> None:
    """Run an authenticated session-lifecycle-scoped loopback proxy."""

    requested_protocols = port_tunnel_requested_protocols(ws)
    tunnel_protocol = (
        PORT_TUNNEL_WEBSOCKET_PROTOCOL
        if requested_protocols.count(PORT_TUNNEL_WEBSOCKET_PROTOCOL) == 1
        else None
    )

    async def reject_before_accept(code: int, reason: str) -> None:
        await ws.accept(subprotocol=tunnel_protocol)
        await close_port_tunnel_websocket(ws, code, reason)

    # Unlike legacy event sockets, a port tunnel is unavailable when the
    # server itself has no token configured. It is a network authority, not a
    # convenience endpoint that may inherit an unauthenticated server mode.
    if not port_tunnel_websocket_authorized(ws):
        await reject_before_accept(
            PORT_TUNNEL_CLOSE_UNAUTHORIZED,
            "AgentsServer authentication is required",
        )
        return
    if tunnel_protocol is None:
        await reject_before_accept(
            PORT_TUNNEL_CLOSE_PROTOCOL_REQUIRED,
            f"WebSocket protocol {PORT_TUNNEL_WEBSOCKET_PROTOCOL} is required",
        )
        return
    try:
        target_port = canonical_port_tunnel_port(port)
    except ValueError as exc:
        await reject_before_accept(PORT_TUNNEL_CLOSE_INVALID_REQUEST, str(exc))
        return

    await ws.accept(subprotocol=PORT_TUNNEL_WEBSOCKET_PROTOCOL)
    reserved = False
    writer: asyncio.StreamWriter | None = None
    websocket_closed = False
    websocket_close_code: int | None = None
    proxy_opened = False

    async def close_once(code: int, reason: str) -> None:
        nonlocal websocket_close_code, websocket_closed
        if websocket_closed:
            return
        websocket_closed = True
        websocket_close_code = code
        await close_port_tunnel_websocket(ws, code, reason)

    try:
        rejection: tuple[int, str] | None = None
        # Count every accepted, authenticated socket before it can queue on a
        # potentially long session lifecycle operation. Archive/delete still
        # own the authoritative admission check below; rejected reservations
        # are released by the common finally block.
        limit = await PORT_TUNNELS.reserve(
            session_id,
            ws,
            owner_task=asyncio.current_task(),
        )
        if limit is not None:
            await close_once(
                PORT_TUNNEL_CLOSE_LIMIT,
                f"Port tunnel {limit} connection limit reached",
            )
            return
        reserved = True
        async with session_lifecycle_lock(session_id):
            session = STORE.sessions.get(session_id)
            if not session:
                rejection = (
                    PORT_TUNNEL_CLOSE_NOT_FOUND,
                    "Session was not found",
                )
            elif bool(session.get("archived")):
                rejection = (
                    PORT_TUNNEL_CLOSE_ARCHIVED,
                    "Archived sessions cannot open port tunnels",
                )
        if rejection is not None:
            await close_once(*rejection)
            return

        try:
            reader, writer = await asyncio.wait_for(
                asyncio.open_connection(
                    host=PORT_TUNNEL_LOOPBACK_HOST,
                    port=target_port,
                ),
                timeout=PORT_TUNNEL_CONNECT_TIMEOUT_SECONDS,
            )
        except asyncio.TimeoutError:
            await close_once(
                PORT_TUNNEL_CLOSE_UNREACHABLE,
                "Loopback service connection timed out",
            )
            return
        except OSError as exc:
            logger.info(
                "port tunnel loopback connect failed session=%r port=%d error=%s",
                session_id,
                target_port,
                concise_error_message(exc),
            )
            await close_once(
                PORT_TUNNEL_CLOSE_UNREACHABLE,
                "No loopback service is reachable on this port",
            )
            return

        # A session lifecycle change while TCP connect is pending must not
        # create a post-archive proxy. The lifecycle lock also closes the
        # admission race with deletion.
        async with session_lifecycle_lock(session_id):
            current = STORE.sessions.get(session_id)
            if not current:
                rejection = (
                    PORT_TUNNEL_CLOSE_NOT_FOUND,
                    "Session was deleted while the tunnel was connecting",
                )
            elif bool(current.get("archived")):
                rejection = (
                    PORT_TUNNEL_CLOSE_ARCHIVED,
                    "Session was archived while the tunnel was connecting",
                )
        if rejection is not None:
            await close_once(*rejection)
            return

        proxy_opened = True
        logger.info(
            "authenticated session-lifecycle-scoped loopback proxy opened "
            "session=%r port=%d",
            session_id,
            target_port,
        )
        result = await bridge_port_tunnel(ws, reader, writer)
        if result is not None:
            await close_once(*result)
    except WebSocketDisconnect:
        pass
    except (ConnectionError, BrokenPipeError):
        await close_once(1011, "Loopback service connection was lost")
    except asyncio.TimeoutError:
        await close_once(1011, "Port tunnel backpressure timed out")
    except Exception as exc:
        logger.warning(
            "port tunnel failed session=%r port=%d error=%s",
            session_id,
            target_port,
            concise_error_message(exc),
        )
        await close_once(1011, "Port tunnel transport failed")
    finally:
        if writer is not None:
            writer.close()
            with suppress(Exception):
                await asyncio.wait_for(
                    writer.wait_closed(),
                    timeout=PORT_TUNNEL_CLOSE_TIMEOUT_SECONDS,
                )
        await close_once(1000, "Port tunnel closed")
        if proxy_opened:
            logger.info(
                "authenticated session-lifecycle-scoped loopback proxy closed "
                "session=%r port=%d close_code=%d",
                session_id,
                target_port,
                websocket_close_code or 1000,
            )
        if reserved:
            # Keep the capacity reservation until every route-owned close has
            # completed. Registry retirement can still remove a done owner if
            # repeated cancellation prevents this final bookkeeping await.
            await PORT_TUNNELS.release(session_id, ws)


@app.websocket("/api/sessions/{session_id}/terminal/ws")
async def session_terminal(
    session_id: str,
    ws: WebSocket,
    columns: int = 120,
    rows: int = 36,
    cwd: str | None = None,
) -> None:
    selected_subprotocol = websocket_endpoint_subprotocol(
        ws,
        TERMINAL_WEBSOCKET_PROTOCOL,
    )
    if not websocket_authorized(ws):
        await ws.accept(subprotocol=selected_subprotocol)
        await ws.close(code=4401)
        return
    if session_id not in STORE.sessions:
        await ws.accept(subprotocol=selected_subprotocol)
        await ws.close(code=4404)
        return
    if bool(STORE.sessions[session_id].get("archived")):
        await ws.accept(subprotocol=selected_subprotocol)
        await ws.close(code=4409)
        return

    cols, lines = terminal_dimensions(columns, rows)
    reserved = await TERMINAL_ATTACHMENTS.reserve(session_id, ws)
    if not reserved:
        await ws.accept(subprotocol=selected_subprotocol)
        await ws.close(code=1012)
        return
    process: subprocess.Popen[bytes] | None = None
    master_fd: int | None = None
    try:
        await ws.accept(subprotocol=selected_subprotocol)
        process, master_fd, name = await TERMINAL_ATTACHMENTS.spawn(
            session_id,
            ws,
            cwd,
            cols,
            lines,
        )
        await ws.send_json({
            "type": "ready",
            "session_id": session_id,
            "name": name,
            "columns": cols,
            "rows": lines,
        })

        async def pump_output() -> None:
            assert master_fd is not None
            while True:
                try:
                    data = await read_terminal_output(master_fd)
                except OSError as exc:
                    if exc.errno in {errno.EIO, errno.EBADF}:
                        return
                    raise
                if not data:
                    return
                await ws.send_bytes(data)

        async def receive_input() -> None:
            assert master_fd is not None
            auto_scroll_mode = False
            try:
                while True:
                    message = await ws.receive()
                    if message["type"] == "websocket.disconnect":
                        return
                    data = message.get("bytes")
                    if data:
                        if auto_scroll_mode:
                            await asyncio.to_thread(exit_terminal_auto_scroll, session_id)
                            auto_scroll_mode = False
                        await write_terminal_input(master_fd, data)
                        continue
                    text = message.get("text")
                    if not text:
                        continue
                    try:
                        control = json.loads(text)
                    except json.JSONDecodeError:
                        continue
                    if not isinstance(control, dict):
                        continue
                    if control.get("type") == "resize":
                        # Control frames are untrusted and may come from a
                        # mixed-version or partially restored renderer. Match
                        # scroll handling: discard malformed geometry without
                        # turning it into a fatal WebSocket error.
                        with suppress(TypeError, ValueError):
                            next_cols, next_rows = terminal_dimensions(control.get("columns"), control.get("rows"))
                            set_pty_dimensions(master_fd, next_cols, next_rows)
                            await asyncio.to_thread(resize_terminal_window, session_id, next_cols, next_rows)
                    elif control.get("type") == "scroll":
                        with suppress(TypeError, ValueError):
                            auto_scroll_mode = await asyncio.to_thread(
                                scroll_terminal_history,
                                session_id,
                                int(control.get("delta") or 0),
                                managed=auto_scroll_mode,
                            )
            finally:
                if auto_scroll_mode:
                    await asyncio.to_thread(exit_terminal_auto_scroll, session_id)

        output_task = asyncio.create_task(pump_output())
        input_task = asyncio.create_task(receive_input())
        done, pending = await asyncio.wait(
            {output_task, input_task},
            return_when=asyncio.FIRST_COMPLETED,
        )
        for task in pending:
            task.cancel()
        await asyncio.gather(*pending, return_exceptions=True)
        for task in done:
            with suppress(WebSocketDisconnect, RuntimeError, OSError):
                task.result()
    except (WebSocketDisconnect, TerminalAttachmentAdmissionClosed):
        pass
    except Exception as exc:
        logger.warning("terminal websocket failed session=%s error=%s", session_id, exc)
        with suppress(RuntimeError):
            await ws.send_json({"type": "error", "message": str(exc)[:1000]})
    finally:
        if process is not None and master_fd is not None:
            await asyncio.to_thread(stop_terminal_client, process, master_fd)
        await TERMINAL_ATTACHMENTS.release(ws)
        with suppress(RuntimeError):
            await ws.close()


@app.websocket("/api/sessions/{session_id}/events")
async def session_events(
    session_id: str,
    ws: WebSocket,
    after: int = 0,
    visible: bool | None = None,
) -> None:
    selected_subprotocol = websocket_endpoint_subprotocol(
        ws,
        EVENTS_WEBSOCKET_PROTOCOL,
    )
    if not websocket_authorized(ws):
        await ws.accept(subprotocol=selected_subprotocol)
        await ws.close(code=4401)
        return
    if session_id not in STORE.sessions:
        await ws.accept(subprotocol=selected_subprotocol)
        await ws.close(code=4404)
        return
    await ws.accept(subprotocol=selected_subprotocol)
    try:
        if not await HUB.reserve(session_id, ws):
            await close_event_websocket_over_capacity(ws)
            return
        cursor = max(0, int(after or 0))
        # Omitted ``visible`` is the legacy protocol (including released iOS
        # clients): it receives every client-safe event rather than the newer
        # timeline-visible subset. Both protocols still require complete,
        # sequence-bound catch-up; the old single 500-row read silently skipped
        # the rest of a long offline gap.
        catchup_visible = visible is True
        boundary = await asyncio.to_thread(
            last_event_seq_from_file,
            events_path(session_id),
        )
        while True:
            cursor = await send_event_catchup(
                session_id,
                ws,
                after=cursor,
                through=boundary,
                visible=catchup_visible,
            )
            if cursor < boundary:
                # Never register a socket with an acknowledged hole. A short
                # scan means the log could not substantiate its own boundary;
                # live delivery cannot repair that missing historical range.
                raise RuntimeError(
                    "event catch-up could not reach its stable boundary"
                )

            # No socket I/O occurs while holding the delivery lock. If an
            # append raced the page stream, capture its new fixed boundary,
            # release the lock, and drain it in the next pass. Registration is
            # performed only in a lock-held instant where no gap remains, so a
            # later append observes the subscriber before it broadcasts.
            activated = False
            async with event_delivery_lock(session_id):
                gap_boundary = await asyncio.to_thread(
                    last_event_seq_from_file,
                    events_path(session_id),
                )
                if cursor >= gap_boundary:
                    activated = await HUB.register_accepted(session_id, ws)
            if cursor >= gap_boundary:
                if not activated:
                    # This should be unreachable after a successful
                    # reservation, but retain retryable overload semantics if
                    # a future lifecycle path releases it early. Socket I/O
                    # remains outside the event-delivery lock.
                    await close_event_websocket_over_capacity(ws)
                    return
                break
            boundary = gap_boundary
        while True:
            await ws.receive_text()
    except WebSocketDisconnect:
        pass
    finally:
        await HUB.unsubscribe(session_id, ws)


@app.websocket("/api/emergency-alerts/events")
async def emergency_alert_events(ws: WebSocket) -> None:
    selected_subprotocol = websocket_endpoint_subprotocol(
        ws,
        EMERGENCY_WEBSOCKET_PROTOCOL,
    )
    if not websocket_authorized(ws):
        await ws.accept(subprotocol=selected_subprotocol)
        await ws.close(code=4401)
        return
    if EMERGENCY_WEBSOCKET_PROTOCOL not in websocket_requested_protocols(ws):
        await ws.accept(subprotocol=selected_subprotocol)
        await ws.close(code=4406)
        return
    await ws.accept(subprotocol=EMERGENCY_WEBSOCKET_PROTOCOL)
    try:
        if not await HUB.reserve(EMERGENCY_HUB_KEY, ws):
            await close_event_websocket_over_capacity(ws)
            return
        # State writes use the same lock. Sending the snapshot before
        # registration while holding it closes the snapshot/live-update race.
        async with STORE._lock:
            sessions = [
                public_emergency_session(sess)
                for sess in sorted_sessions(list(STORE.sessions.values()))
                if not sess.get("_fork_initializing")
                and active_emergency_alerts(sess)
            ]
            await asyncio.wait_for(
                ws.send_json({
                    "type": "emergency_snapshot",
                    "server_identity": server_identity(),
                    "sessions": sessions,
                }),
                timeout=WEBSOCKET_SEND_TIMEOUT_SECONDS,
            )
            activated = await HUB.register_accepted(EMERGENCY_HUB_KEY, ws)
        if not activated:
            await close_event_websocket_over_capacity(ws)
            return
        while True:
            await ws.receive_text()
    except WebSocketDisconnect:
        pass
    finally:
        await HUB.unsubscribe(EMERGENCY_HUB_KEY, ws)


@app.get("/api/sessions/{session_id}/diffs/{run_id}")
async def get_turn_code_diff(session_id: str, run_id: str) -> FileResponse:
    if session_id not in STORE.sessions:
        raise HTTPException(status_code=404, detail="session not found")
    if not re.fullmatch(r"[A-Za-z0-9._-]+", run_id or ""):
        raise HTTPException(status_code=404, detail="code diff not found")
    patch_path = code_diffs_dir(session_id) / f"{run_id}.patch"
    if not patch_path.is_file():
        raise HTTPException(status_code=404, detail="code diff not found")
    return FileResponse(
        patch_path,
        media_type="text/x-diff; charset=utf-8",
        filename=f"{run_id}.patch",
        content_disposition_type="inline",
    )


